// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":299,"question":"ما حكم مَن تعدَّى الميقات وهو قاصدٌ العمرة لمكة من المدينة، ولكن بعد وصولي إلى جدة أمضيتُ مدةً فيها، وبعد ذلك أحرمتُ من جدة وذهبتُ إلى مكة مُحْرِمًا، فماذا يجب عليَّ؟","title":"حكم من قصد العمرة ثم تعدَّى الميقات","answer":"الجواب: الذي يتعدى الميقات وهو قاصدٌ العمرة أو الحج عليه دمٌ، مَن خرج من المدينة وما أحرم إلا من جدة، وهو قاصدٌ العمرة، أو قاصدٌ الحج؛ يكون عليه دمٌ يُذبح في مكة للفقراء؛ لأنه ترك الواجب وهو الإحرام من الميقات، هكذا من جاء من الرياض قاصدًا العمرة، ثم ما أحرم إلا من جدة؛ عليه دمٌ، وهكذا مَن جاء من مصر أو الشام ولم يُحرم إلا من جدة عليه دمٌ؛ لأنه تجاوز الميقات.\nأما لو جاء وما نوى عمرةً ولا حجًّا، جاء جدة لزيارة بعض إخوانه، أو للبيع والشراء، ما عنده نية حجٍّ ولا عمرة، ثم بعد ذلك عزم على العمرة، طرأ عليه أن يعتمر، هذا يُحرم من جدة؛ لأنه حين جاوز الميقات ما عنده نيَّة، إنما نوى في جدة، فهذا يُحرم من جدة ولا بأس.\nهكذا مَن خرج من المدينة ما عنده نيَّة، إنما قصد جدة لأجل بيعٍ وشراء، أو زيارة بعض الأقارب، أو العلاج، فلما وصل جدة طرأ عليه، قال: ما دمتُ قريبًا أُحبّ أني أعتمر، يُحرم من جدة، نعم.\nأما إنسانٌ قاصد من المدينة، قاصد من الرياض العمرة، ثم يمرّ بالميقات ولا يُحرم، لا، هذا غلطٌ، يجب أن يُحرم من الميقات، فإذا جاوزه وأحرم من دونه -من جدة أو غيرها- يكون عليه دمٌ.","link":"https://binbaz.org.sa/fatwas/4301/حكم-من-قصد-العمرة-ثم-تعدى-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0348.mp3","categories":["المواقيت"]},{"id":346,"question":"أنا في مكة، فهل يصحّ لي أن آخذ العمرة والحجّ من بيتي دون خروجي إلى الحلّ؟","title":"هل يجوز لأهل مكة الحج من بيوتهم؟","answer":"الجواب: ليس لك ذلك، المشروع الخروج إلى الحِلّ، هذا الذي عليه عامَّة العلماء، وهو كالإجماع منهم، والقول بجواز هذا شاذٌّ لا يُعوَّل عليه، جواز الإحرام من الحرم قولٌ شاذٌّ لا وجهَ له، الصواب أنه يخرج إلى الحلِّ كما ثبت في \"الصحيحين\" من حديث عائشة رضي الله عنها: أن النبي ﷺ لما طلبت منه العمرة أمرها أن تخرج إلى الحلِّ، أمر أخاها عبدالرحمن أن يخرج بها إلى الحلِّ، فأحرمت من التَّنعيم،  وأما حديث ابن عباس: ومَن كان دون ذلك فمُهَلُّه من حيث أنشأ حتى أهل مكة من مكة، فهذا عامٌّ مخصوصٌ، يُراد به الحجّ دون العمرة، بدليل حديث عائشة، وحديث عائشة أخصّ، وهو مُتأخِّر أيضًا.","link":"https://binbaz.org.sa/fatwas/4435/هل-يجوز-لاهل-مكة-الحج-من-بيوتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0399.mp3","categories":["المواقيت"]},{"id":392,"question":"جئتُ من باكستان، وأحرمتُ من جدة، فما الحكم؟","title":"ما حكم من جاء من باكستان وأحرم في جدة؟","answer":"الجواب: هذا فيه تفصيل: إن كنتَ حين جئتَ من باكستان ناويًا الحجَّ فالواجب عليك الإحرام من الميقات الشرعي، وهو ميقات الشرقيين، ميقات نجد ومَن كان على سبيلهم؛ لأن الهند وباكستان شرقيتان، فميقاتهما وادي قرن. إلا إذا جاءوا من طريق المدينة فميقاتهم المدينة، أو من طريق اليمن فميقاتهم يلملم، أما إذا جاءوا من الطريق الشرقي فإنَّ ميقاتهم وادي قرن، فإذا جاوزه وأحرم من جدة فعليه دمٌ؛ لأنه جاوز الميقات. أما إن كان أتى جدة لحاجاتٍ، ما قصد حجًّا ولا عمرةً، وإنما جاء لحاجاتٍ أخرى، ثم أنشأ نية الحج أو العمرة من جدة؛ فهذا يُحرم من جدة كما تقدم؛ لأنه ما نوى الحجَّ ولا العمرة قبل ذلك.","link":"https://binbaz.org.sa/fatwas/4777/ما-حكم-من-جاء-من-باكستان-واحرم-في-جدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0448.mp3","categories":["الإحرام","المواقيت"]},{"id":617,"question":"بعض القادمين من خارج المملكة إذا وصلوا جدة يقولون نجلس ثلاثة أيام في جدة ثم نحرم من الميقات؟","title":"حكم من جاوز الميقات للبقاء في جدة أولاً","answer":"الجواب: يلزمهم أن يعودوا إلى الميقات ويحرمون من الميقات وهم جايين للحج والعمرة يلزمهم يعودون ليحرموا من الميقات لا يجوز لهم تجاوز الميقات، الرسول ﷺ قال: هن لهن ولمن أتى عليهن من غير أهلهن لمن أراد الحج أو العمرة فلا بدّ إن أرادوا الحج أو العمرة ومروا من الميقات أن يحرموا منه فإن تجاوزوه يعودون إليه فإن أبوا ولم يعودوا؛ لزمهم دم.","link":"https://binbaz.org.sa/fatwas/6457/حكم-من-جاوز-الميقات-للبقاء-في-جدة-اولا","audio":"undefined","categories":["المواقيت","الإحرام"]},{"id":621,"question":"القادمون من السودان أين ميقاتهم؟","title":"أين الميقات للقادمين من السودان؟","answer":"الجواب: إذا حاذوا الجُحْفة أحرموا من محاذاة الجحفة، فإذا جاءوا من طريق لا يحاذون فيه الميقات أحرموا من جدة.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6483/اين-الميقات-للقادمين-من-السودان","audio":"https://files.zadapps.info/binbaz.org.sa/maram189.mp3","categories":["المواقيت","الإحرام"]},{"id":622,"question":"من ذهب إلى جدة لغرض أو  للسياحة وهو قاصد الخروج إلى الرياض للعمرة لكن قال أذهب أولاً إلى جدة ثم نعتمر؟","title":"حكم من أراد العمرة لكن يريد زيارة جدة قبلها","answer":"الجواب: إذا قضى حاجته من جدة يرجع للميقات، الميقات الذي مر به إذا كان ناويًا قبل أن يمر منه ناويًا من بلده، وإما يُحْرم مُعْجَّلاً من الميقات ويؤدي العمرة ثم يروح لجدة، وإلا إذا قضى غرضه من جدة يرجع إلى الميقات.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6484/حكم-من-اراد-العمرة-لكن-يريد-زيارة-جدة-قبلها","audio":"https://files.zadapps.info/binbaz.org.sa/maram190 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":623,"question":"إذا جاوزت الطائرة الميقات، فإذا وصل المطار هل يجوز أن يذهب إلى رابغ؟","title":"ماذا يفعل راكب الطائرة إذا جاوز الميقات؟","answer":"الجواب: لا، يحرم من الميقات الذي مر عليه.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6486/ماذا-يفعل-راكب-الطاىرة-اذا-جاوز-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/maram191  - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":625,"question":"إذا كان المسافر بالطائرة وصلوا بعد نصف ساعة فمروا من فوق الميقات ولبى يخشى أن يفوته الميقات؟","title":"حكم احتياط المحرم على الطائرة في الميقات","answer":"الجواب: إذا احتاط لا بأس، إذا احتاط قبل أن يصل الميقات لا بأس، الاحتياط مطلوب.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6491/حكم-احتياط-المحرم-على-الطاىرة-في-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/maram193 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":626,"question":"النبي ﷺ هو الذي وَقَّت رابغ؟","title":"هل الجحفة ورابغ شيء واحد في المواقيت؟","answer":"السؤال: هو الذي وقت الجُحْفة، والجحفة هي ورابغ شيء واحد، لكن رابغ أرفق للناس من الجحفة.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6492/هل-الجحفة-ورابغ-شيء-واحد-في-المواقيت","audio":"https://files.zadapps.info/binbaz.org.sa/maram194 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":627,"question":"الإحرام قبل الميقات؟","title":"ما حكم الإحرام قبل الميقات؟","answer":"الجواب: مكروه، وقد أحرم بعض السلف من الشام، لكن الأوْلى ترك ذلك واتباع السُّنة، لا يحرم إلا من الميقات.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6493/ما-حكم-الاحرام-قبل-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/maram195 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":628,"question":"الإحرام عقب الصلاة، أي صلاة مفروضة أو نافلة؟","title":"هل يكون الإحرام عقب صلاة فرض أو نافلة؟","answer":"الجواب: نعم، إذا كانت فريضة تُغْنِي، النبي ﷺ أحرم بعد الظهر. وإذا كان ما في فريضة؛ شُرع له أن يصلي ركعتي وضوء ثم يُحْرِم بعدهما بعد ركوب الدابة.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6494/هل-يكون-الاحرام-عقب-صلاة-فرض-او-نافلة","audio":"https://files.zadapps.info/binbaz.org.sa/MARAM196 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":634,"question":"في واحد نوى التمتع هل يقدر يغير إلى قِران؟","title":"متى يجوز تغيير النية من التمتع إلى قِران؟","answer":"الجواب: إذا كان معه الهَدْى يغير إلى قِران، وإذا كان ما معه هدي فالسُّنة يطوف ويسعى ويقصِّر ويَحلّ، ولا يُغَيِّر، هذه هي السنة: إذا لبى بالعمرة يطوف ويسعى ويقصِّر ويَحلّ، وإن كان لبى بالحج السُّنة أن يجعلها عمرة أيضاً، حتى لو لبى بالحج يفسخها إلى عمرة يطوف ويسعى ويقصر ويجعلها عمرة ويَحلّ، كما أمر النبي ﷺ الصحابة بذلك، إلا من ساق الهدي؛ من كان مع هدي إبل وإلا بقر وإلا غنم فهذا يُحْرِم بالحج والعمرة جميعًا ولا يَحلّ إلا في أيام النحر حتى ويَحلّ من حجه أو عمرته.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6553/متى-يجوز-تغيير-النية-من-التمتع-الى-قران","audio":"https://files.zadapps.info/binbaz.org.sa/maram202 - 03 - .mp3","categories":["المواقيت","الإحرام"]},{"id":720,"question":"شخصٌ جاء إلى جدة عن طريق المدينة، فلما مكث بجدة يومان أراد أن يأخذ عمرةً، فهل يُحْرِم من جدة وليس عليه شيءٌ؟ أم أنَّ عليه دمًا باعتبار أنه لم يُحْرِم من الميقات؟","title":"حكم من جاء إلى جدة ثم أراد العمرة","answer":"الجواب: هذا فيه تفصيل ينبغي أن نفهمه جيدًا: هذا الذي جاء من المدينة إلى جدة، أو من الرياض إلى جدة، أو من المنطقة الشرقية إلى جدة، أو من الشام إلى جدة، أو غير ذلك، إن كان ما أراد عمرةً، ما نوى عمرةً، جاء لحاجةٍ في جدة، ما أراد عمرةً ولا حجًّا، جاء لحاجةٍ: يزور أخًا له، يزور صاحبًا له، للتِّجارة، لغير هذا من الحاجات، فهذا له أن يُحْرِم من جدَّة؛ لأنه ما نوى إلا في جدة، إذا نوى العمرة في جدة يُحْرِم من جدة؛ لأنه حين مرَّ بالميقات ما كانت عنده نيَّة، حينما مشى من المدينة أو من الرياض أو من الدمام أو من الشام أو غير ذلك ما قصد عمرةً ولا حجًّا، إنما أراد جدة لمصلحةٍ وحاجةٍ، فهذا إذا نوى في جدة يُحرم منها؛ لقول النبي ﷺ لما وقَّت المواقيت: هنَّ لهنَّ ولمن أتى عليهنَّ من غير أهلهنَّ ممن أراد الحجَّ والعمرةَ، ثم قال عليه الصلاة والسلام: ومَن كان دون ذلك فمهلّه من حيث أنشأ، مهلّه يعني: محل إهلاله، من حيث أنشأ، حتى أهل مكة من مكة.\nيدخل في هذا مَن جاء من المدينة إلى جدة ما أراد العمرة، لكن لما وصل جدة وأقام بها قال: أنا قريبٌ، أريد أن آخذ عمرةً؛ لا بأس، يُحرم من جدَّة؛ لأنه إنما أنشأ بها، أو جاء من الرياض أو من الدمام أو من الإحساء أو من غير ذلك إلى جدة يزور قريبًا له، ما نوى عمرةً، أو للتِّجارة ما نوى عمرةً، ثم طرأ عليه في جدة أن يعتمر؛ يُحرم منها.\nأما إنسانٌ جاء من الرياض أو من المدينة لقصد العمرة، فهذا لا يتجاوز الميقات: إن كان من المدينة يُحرم من ميقات المدينة، وإن كان من الرياض أو الإحساء أو غيرها يُحرم من ميقات أهل نجدٍ: السيل، من طريق الطائف، إذا كان من طريق الطائف هو السيل المعروف، ولا يتجاوز ذلك إلا بإحرامٍ، إذا جاوزه وأحرم من جدة وهو ناوٍ العمرة حين توجَّه؛ فهذا عليه دمٌ، يُذبح في مكة للفقراء؛ لأنه ترك واجبًا وهو الإحرام من الميقات، والله أعلم.","link":"https://binbaz.org.sa/fatwas/20561/حكم-من-جاء-الى-جدة-ثم-اراد-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0519فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["المواقيت","الإحرام"]},{"id":859,"question":"إنَّ أهل المغرب الإسلامي يُعانون من مشكل الإحرام من الميقات المُخصص لهم، حيث يمرون عليه وهم في الجو، حيث لا يستطيعون الإحرام في الطائرة، ولا في المطارات، وقد أفتى بعضُهم لهم بالإحرام في جدة، ما رأيكم في هذه الفتوى؟","title":"حكم الإحرام بعد الميقات لتعذُّره بالطائرة","answer":"الجواب: قد كتبنا عليها ردًّا، وكتبنا لأخينا الذي أفتاهم الشيخ عبدالله قنو: هذا غلط، وليس في الإحرام بالطائرة مشقَّة، الإحرام: لبيك عمرة، لبيك حجًّا، ما فيه مشقَّة كلام: اللهم لبيك حجًّا، أو: اللهم لبيك عمرة، هذا ما فيه مشقَّة على أحدٍ، إذا وصل الميقات أو دنا من الميقات وخاف أن يتجاوزه قبل أن يصل إليه يخاف: يُلبي ولو قبله حتى يحتاط لإحرامه.\nوأما الغسل والتَّطيب ما هو بلازمٍ، وإن تطيب في الطائرة قبل أن يُحرم فهو ميسورٌ، يحطّ الطيب جنبه، أو معه، أو في شنطته، ويتطيب قبل أن يُحرم، والغسل ما هو بلازمٍ، وفي إمكانه أن يغتسل في بيته قبل أن يُحرم، يغتسل في بيته قبل أن يركب الطائرة، ولو مكث في الطائرة يومًا أو نصف يومٍ، يغتسل في بيته، والغسل سُنَّة، ما هو بلازمٍ.\nكذلك لباس الإحرام يلبسه في بيته، يلبسه في الطائرة قبل أن يدخل الميقات، وهو في حال السعة، يلبس الإزار والرداء، ويلبس الإزار في بيته أيسر عليه، يعدّه في بيته، ويلبس ملابس فوق الإزار، فإذا جاء حذو الميقات خلع الملابس ولبس الرداء كله، مُيَسَّرٌ أن نفعل هذا، الإنسان يفعل في بيته ما يتيسَّر: يتطيب، ويغتسل، ويلبس الإزار وثيابه فوق الإزار، فإذا قرب من الميقات خلع الملابس ولبس الرداء ولبَّى، وليس في هذا مشقَّة، ولا يجوز تجاوز الميقات أبدًا، والفتوى غلط.","link":"https://binbaz.org.sa/fatwas/20893/حكم-الاحرام-بعد-الميقات-لتعذره-بالطاىرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0688من لايستطيع أن يحرم في الطائرة أو المطار فهل يجوز له أن يحرم من جدة؟ ابن باز فتاوى المحاضرات.mp3","categories":["المواقيت","الإحرام"]},{"id":871,"question":"قد ذكرتُم جزاكم الله خيرًا أنه لا يجوز تجاوز الميقات إلا بالإحرام، فما الحكم في مثل حالتنا، حيث أحرمنا من جدة، علمًا بأنه أفتانا بعضُ الناس بجواز ذلك، وأنَّ الإحرام جائزٌ من جدة، وبالطائرة، ونسبوا ذلك لبعض أهل العلم؟ أفتونا مأجورين.","title":"حكم من تجاوز ميقات الإحرام المحدد له","answer":"الجواب: إذا كنتم جئتُم بقصد العمرة من بلادكم ومررتُم على المواقيت ناوين العمرة، فعليكم دمٌ، والفتوى هذه لا وجهَ لها، قد أجمع العلماء جميعًا على أنَّ الواجب على مَن مرَّ على الميقات ناويًا الحجَّ والعمرة يُحرم منه، هذا بإجماع أهل العلم؛ لقوله ﷺ في حديث ابن عباس، يقول ابن عباس: \"وقَّت النبيُّ ﷺ لأهل المدينة ذا الحليفة، ولأهل الشام الجحفة، ولنجد قرن المنازل، ولأهل اليمن يلملم: هنَّ لهنَّ ولمن أتى عليهنَّ من غير أهلهنَّ ممن أراد الحجَّ والعمرةَ\".\nفإذا كنتم مررتُم عليها بنية العمرة فقد أخطأتُم في تجاوزها، وعليكم دمٌ، مع التوبة والاستغفار، وليس كل فتوى تكون جديرةً بالأخذ، لا بد للإنسان أن يتثبت في الأمور، ولا يسأل إلا أهل العلم المعروفين بالعلم والفضل، والخشية لله، والورع، وقلة التسرع، يحتاط لدينه.\nوقد أجمع العلماءُ على أنَّ هذه المواقيت لا يجوز تجاوزها إلا بإحرامٍ، وإنما اختلفوا: هل عليه دمٌ أم لا؟\nالجمهور على أنَّ مَن جاوزها -عليه أكثر العلماء- عليه دمٌ؛ لقول ابن عباسٍ رضي الله تعالى عنهما: \"مَن ترك نُسُكًا أو نسيه فليُهرق دمًا\"، وهذا كلامٌ جيدٌ، وبعض أهل العلم جعل له حكم الرفع؛ لأنه لا يُقال من جهة الرأي.\nس: يصعب عليهم الآن الدَّم، ما عندهم مقدرة؟\nالشيخ: بعد ذلك يرسل، ولو بعد ذلك، أو يصوم مَن عجز عشرة أيام، أو يُرسل من بلاده مع الحجّاج، أو مع غير الحجّاج، أو يُوكّل في مكة مَن يذبحه ولو بعدما يصل إلى بلاده، ما هو بلازمٍ الآن: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/20899/حكم-من-تجاوز-ميقات-الاحرام-المحدد-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0694فما الحكم فمن أحرم من جدة بعد تجاوز الميقات للضرورة نباءً على فتاوى بالجواز؟ ابن باز.mp3","categories":["المواقيت","الإحرام"]},{"id":902,"question":"هل يقع من أهل مكة تمتع وقران؟","title":"هل يقع من أهل مكة تمتع وقران؟","answer":"الشيخ: نعم، لا بأس، لكن ليس عليهم هدي التمتع والقران، فلهم أن يمتعوا بالعمرة في أشهر الحج، ولهم أن يقرنوا بينهما، لكن الأفضل لهم الحج المفرد؛ لأنَّ الله وسَّع لهم العمرة، متى شاءوا اعتمروا، فلو اعتمروا في أشهر الحج فلا بأس.","link":"https://binbaz.org.sa/fatwas/20941/هل-يقع-من-اهل-مكة-تمتع-وقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0737هل يقع من أهل مكة تمتع وقِران؟ ابن باز فتاوى المحاضرات.mp3","categories":["المواقيت","الإحرام"]},{"id":1074,"question":"أنا من أهل الطائف، وفي مرةٍ نويتُ العمرة من الطائف، ولكن كان هناك بعض الأقرباء في جدة، فذهبتُ إلى جدة وأحرمتُ من هناك، فهل عليَّ في ذلك شيءٌ؟","title":"حكم الإحرام من جدة لمن نوى عمرةً بالطائف","answer":"الجواب:\nإذا كنتَ أردتَ العمرة من الطائف وتساهلتَ ورحت واعتمرتَ من جدَّة عليك دمٌ؛ لأن الواجب عليك الإحرام من الطائف، من ميقات الطائف. أما إذا كنتَ حين ذهبتَ إلى جدة ما نويتَ العمرة، أو عندك تردُّدٌ ولم تعزم إلا من جدَّة؛ فليس عليك شيءٌ. أما إذا عزمتَ على العمرة وصممتَ عليها فعليك أن تُحرم من الميقات، وإذا ذهبتَ إلى جدة لا تُحرم من جدة، ارجع إلى الميقات، واحرم من الميقات، فإن أحرمتَ من جدَّة فعليك دمٌ؛ لأنك جاوزتَ الميقات وأنت عازمٌ على العمرة.","link":"https://binbaz.org.sa/fatwas/21143/حكم-الاحرام-من-جدة-لمن-نوى-عمرة-بالطاىف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0939تويت العمرة من الطائف وذهبت إلى جدة لزيارة أقربائي وأحرمت من هناك فهل عليَّ في ذلك شيء؟.mp3","categories":["المواقيت","الإحرام"]},{"id":1226,"question":"رجلٌ تجاوز الميقات دون إحرامٍ، ولم يجد قيمةَ الدم، ولا يستطيع الصيام، فماذا يفعل؟","title":"حكم من لا يستطيع الفدية ولا الصيام في الحج","answer":"الجواب:\nيبقى عليه الدم أو الصيام حتى يستطيع، إذا أحرم من دون الإحرام، جاوز الميقات ولم يُحرم، وأحرم من داخل مكة، أو من الطريق، فقد أساء، وعليه التوبة إلى الله، وعليه دمٌ متى قدر، فإن عجز يصوم عشرة أيام متى قدر، مثل: سائر الديون، يبقى دينًا كسائر الديون، فإن أوفى الله عنه في الدنيا وإلا فمعذورٌ، والحمد لله.","link":"https://binbaz.org.sa/fatwas/21286/حكم-من-لا-يستطيع-الفدية-ولا-الصيام-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1029رجل تجاوز الميقات دون أحرام ولم يجد قيمة الدم ولا يستطيع الصيام فما يفعل؟ ابن باز.mp3","categories":["المواقيت","الإحرام"]},{"id":1230,"question":"جئتُ من مصر للعمل بمكة منذ أربعة شهور، فهل لي أن أُهلّ بالإفراد بالحج من منزلي بالعزيزية؟ أرجو التوضيح، وجزاكم الله خيرًا.","title":"من أين يُحْرِم بالحج أهل مكة والمقيمون فيها؟","answer":"الجواب:\nنعم، إذا قدم الحاجُّ وأدَّى العمرةَ فإنه إذا جاء وقتُ الحجِّ يوم الثامن يُلبي بالحج من منزله إن كان في الأبطح أو في داخل مكة، الصحابة  الذين حلّوا أمرهم النبيُّ ﷺ أن يُحرموا من منازلهم في الأبطح، أن يُهلُّوا بالحج من منازلهم، فالذي أتى مكةَ وفرغ من العمرة وجلس إلى وقت الحج يُحرم من منزله، وهكذا أهل مكة والمقيمون فيها من غير أهلها: إذا جاء وقتُ الحجِّ أحرموا من منازلهم، وليس هناك حاجة إلى الدخول إلى المسجد الحرام، ولا يُشرع ذلك، بل يُحْرِم من مكانه، ويتوجَّه إلى مِنى يوم الثامن حتى يُصلي بها الظهر والعصر والمغرب والعشاء والفجر، ولا يُشرع لهم الدُّخول إلى مكة ليطوفوا، ليس على هذا دليلٌ.","link":"https://binbaz.org.sa/fatwas/21282/من-اين-يحرم-بالحج-اهل-مكة-والمقيمون-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1025قدمت من مصر لمكة منذ أربعة أشهر فهل لي أن أهلَّ بالإفراد من منزلي بالعزيزة ارجو التوضيح؟ابن باز.mp3","categories":["المواقيت","الإحرام"]},{"id":1291,"question":"يعلم سماحتكم أنه يُكلَّف بعض الأطباء بالعمل في خدمة الحجيج في فترة الحج، فهل يجوز للطبيب المُكلَّف بالعمل أن يُحْرِم من مكان عمله في مكة؟","title":"حكم إحرام الطبيب في الحج من مكان عمله","answer":"الجواب:\nنعم، له أن يُحرم إذا كان دخل من دون إحرامٍ، ما نوى إحرامًا، وإنما بدا له الإحرام بعد ذلك، يُحرم من مكانه خارج الحرم، من عرفات إن كان فيها، من الجعرانة إذا كان لعمرةٍ.  أما إذا كان للحج يُحرم من مكانه، ولو في منى، ولو أنه في منى يُحرم من مكانه إذا كان في الحجِّ، بشرط أنه دخل ما عنده نيَّة.  أما إذا كان داخلًا حين مرَّ بالميقات وهو ناوٍ يُحرم من الميقات، وإن كان ما أحرم يرجع إليه ويُحرم منه.\nأما إن كان لا، جاء للعمل، ما عنده نية: لا حج، ولا عمرة، جاء للعمل، ثم بدا له، سُمح له أن يحجَّ أو يعتمر: إن كان عمرةً يُحرم من الحلِّ للعمرة: الجعرانة أو التَّنعيم أو عرفات، من خارج الحرم، خارج الأميال، يخرج إلى الحلِّ ويُحرم من الحلِّ. أما إن كان حجَّ فيُحرم من مكانه في منى في يوم الثامن، أو يوم عرفة، أو في عرفات يُحرم منها والحمد لله.\nس: طيِّب، لو ما سمحت له الجهة التي ابتعثته للحجِّ؟\nالشيخ: لا يُحْرِم، إذا كان ما سمحوا له لا يُحرِم، يعمل ولا يُحْرِم، عليه السمع والطاعة؛ لأنه إذا ما أحرم يكون أفْرَغَ للعمل.","link":"https://binbaz.org.sa/fatwas/21344/حكم-احرام-الطبيب-في-الحج-من-مكان-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1087يكلف بعض الأطباء في خدمة الحجاج فهل يجوز له آن يحرم من مكان عمله؟ ابن باز.mp3","categories":["المواقيت","الإحرام"]},{"id":1297,"question":"هل يجوز (للمرأة) الكشف في الحج؟","title":"هل يجوز كشف المرأة وجهها في الحج؟","answer":"الجواب:\nلا تلبس النقاب، ولكن تستر وجهها بغير النقاب: بخمارٍ ونحوه مما يستر الوجه، على وجهٍ لا يمنعها السير، تجعل غطاءً لا يمنعها السير والنظر إلى الطريق، لكن غير النقاب.\nالنقاب: البُرقع الذي يُجعل على الوجه، الخاص بالوجه، يكون فيه نقب أو نقبان، هذا يُسمَّى: نقابًا، منع النبيُّ ﷺ من لبسه في حقِّ المحرمة، والقفازان كذلك في يديها حال إحرامها، ولكن تُغطي يديها ووجهها بغير ذلك، قالت عائشةُ رضي الله عنها: \"كنا مع النبي ﷺ في الحجِّ، فإذا دنا منا الرجال سدلت إحدانا جلبابها على وجهها\"، أو قالت: \"خِمارها على وجهها\"، \"فإذا بَعُدُوا كَشَفْنا\".","link":"https://binbaz.org.sa/fatwas/21372/هل-يجوز-كشف-المراة-وجهها-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1115سائلة تقول هل يجوز كشف الوجه في الحج؟ ابن باز فتاوى.mp3","categories":["المواقيت","الإحرام"]},{"id":1301,"question":"نحن بعض منسوبي المدرسة، كان أحد زملائنا في قسم التربية الإسلامية في المناهج قال إن أنساك الحج اثنان فقط، هما: القِرَان، والتَّمتع، وليس هناك نُسُكٌ ثالث كما يزعم البعضُ، ويُسميه: الإفراد، وقد أسمعنا مجموعةً من الأدلة، وقول بعض أهل العلم، مثل: الشوكاني، وابن حزم، وغيره، وقال: ارجعوا إلى كتاب \"البخاري\" و\"زاد المعاد\"، فما القول الراجح في هذه المسألة أثابكم الله؟","title":"ما الصواب في أنواع أنساك الحج؟","answer":"الجواب:\nهذا غلطٌ باطلٌ، أجمع العلماء على أن الأنساك ثلاثة: حج مفرد، وقران، وتمتع، بإجماع أهل  العلم، وقد خيَّر النبيُّ ﷺ الصحابة في الميقات في حجة الوداع بين ذلك.  ولكن يُستحب لمن قدم مكة وليس معه هدي وقد أحرم بالحج أو بالقِرَان أن يجعلهما عمرةً، سواء كان حجًّا أو قِرَانًا، إذا كان ما معه هَدْي؛ فالمشروع له أن يجعلها عمرةً: يطوف ويسعى ويُقَصِّر، وإلا فالحج غير منسوخ، نُسُكُه مستقل، والقران نُسُكُه مستقل.\nوقد أقر النبيُّ ﷺ عروة بن المضرس على إحرامه بالحج، ولم يأمره بفسخه، المقصود أنَّ الفسخ سُنة، على الصحيح سُنة، وقال بعضُهم: إنه خاصٌّ بالصحابة، كما قال أبو ذرٍّ: إنه خاصٌّ بنا، والصواب أنه ليس خاصًّا بالصحابة، لكن يُستحب لمن قدم مكة مُحْرِمًا بالحج مُفردًا أو قارنًا وليس معه هدي: لا إبل، ولا بقر، ولا غنم، أن يجعلها عمرةً: يطوف ويسعى ويُقَصِّر ويحلّ، أما أنه زعم أنه باطلٌ، وأنه نسخ؛ فهذا غلطٌ من قائله.","link":"https://binbaz.org.sa/fatwas/21368/ما-الصواب-في-انواع-انساك-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1111رجل يقول أن أنساك الحج أثنان القران والتمتع وليس هناك نسك ثالث فما رأيكم؟.mp3","categories":["المواقيت","الإحرام"]},{"id":1565,"question":"إذا كان الشخص من أهل الرياض وذهب إلى المدينة زيارةً، من أين يُحْرِم إذا أراد العمرة؟","title":"حكم مَن أتى من بلده للمدينة ثم أراد العمرة","answer":"الجواب:\nمن ميقات المدينة، إذا أراد العمرة وهو في المدينة يُحرم من ميقات المدينة، وإذا أراد العمرة وهو في الطائف يُحرم من ميقات الطائف، وإذا أراد العمرة وهو في اليمن يُحرم من ميقات اليمن.\nس: وهو في الرياض أحسن الله إليك؟\nج: نعم، ولو، طالما أنه توجَّه إلى المدينة يُحرم من ميقات المدينة.","link":"https://binbaz.org.sa/fatwas/21668/حكم-من-اتى-من-بلده-للمدينة-ثم-اراد-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أتى من الرياض إلى المدينة ثم أراد العمرة.mp3","categories":["المواقيت","الإحرام"]},{"id":1740,"question":"قدم إلى مكة مُفْرِدًا، وطاف طواف القدوم، وسعى وقدَّم السعي، وبعدما قدَّم السعي قال: لماذا لا أُحوّلها إلى عمرةٍ وأتمتع، فهل له ذلك مع أنه قد نوى الإفراد؟","title":"حكم تحويل نية الحج من الإفراد إلى التمتمع","answer":"الجواب:\nهذا الأفضل، يُقَصِّر ويحلّ، ولو.\nس: يعني: له ذلك؟\nج: نعم، نية عمرة.","link":"https://binbaz.org.sa/fatwas/21847/حكم-تحويل-نية-الحج-من-الافراد-الى-التمتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يصنع من أراد تحويل النية من المفرد إلى التمتمع.mp3","categories":["المواقيت","الإحرام"]},{"id":2242,"question":"الرجال في الحج هل يجوز لهم أن يُغيّروا النيةَ بعد الدخول في نُسُكٍ معينٍ إلى نية نُسُكٍ آخر؟","title":"حكم تغيير النية في الحج مِن نُسُك إلى آخر","answer":"الجواب:\nحسب الشرع، إذا دخل في حجٍّ أو حجٍّ وعمرةٍ فله أن يجعلهما عمرةً، وهو السنة، فيفسخهما عمرةً، أمَّا إذا أحرم بعمرةٍ فليس له أن ينتقل عنها، لكن له أن يُدْخِل عليها الحجّ فيكون قارنًا.\nس: مَن حجَّ متمتّعًا هل له أن يجعل العمرةَ لشخصٍ والحجَّ لشخصٍ؟\nج: نعم لا بأس، يُهلّ بالعمرة لنفسه، وبعد التحلل يُلبي بالحج عن أبيه، أو عن أمه، أو عن زوجته.\nس: كيف يكون الفسخُ من حجٍّ إلى عمرةٍ؟\nج: بالنية.\nس: والإحرام؟\nج: لبَّى بالحجِّ من الميقات، أو بالحجِّ والعمرة جميعًا، ثم لما وصل مكةَ جعلها عمرةً؛ فطاف وسعى وقصَّر أو حلق، مثلما أمرهم النبيُّ ﷺ إذا لم يكن معه هدي.","link":"https://binbaz.org.sa/fatwas/22365/حكم-تغيير-النية-في-الحج-من-نسك-الى-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تغيير النية في الحج من نسك إلى نسك آخر.mp3","categories":["المواقيت","الإحرام"]},{"id":2718,"question":"رجل أتى من الكويت وزار المدينة وأحرم من ميقات أهل المدينة، وكان هذا قبل رمضان، يريد أن يعتمر في رمضان؟","title":"مِن أين يُحْرِم مَنْ أتى مِن الكويت للمدينة؟","answer":"الجواب: يعتمر مِنْ الحِلّ، من التنعيم أو من عرفات أو من الجعرانة، من الحِلّ خارج الحدود.\nس: لا يشترط أن يكون من...؟\nالشيخ: ما هو بلزوم لا، لمّا صار في مكة وأدى العمرة، إذا أدى عمرة يخرج إلى الحِلّ مثلما فعلت عائشة اعتمرت من المدينة، ثم أحرمت بالعمرة الثانية من التنعيم، بأمر النبي عليه الصلاة والسلام.\nس: الذهاب إلى جدة هل يُحْرِم؟\nالشيخ: إذا ذهب إلى جدة أو غيرها ما في بأس، لكن الله يسّر عليه الأقرب.\nس: من قال إن هذا خاص بالحائض؟\nالشيخ: مِنْ كِيسِه، إن كان كِيسُ الناس يُطاع وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7].","link":"https://binbaz.org.sa/fatwas/22861/من-اين-يحرم-من-اتى-من-الكويت-للمدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أين يحرم من أتى من الكويت إلى المدينة ويريد العمرة.mp3","categories":["المواقيت","الإحرام"]},{"id":2719,"question":"كثير من الإخوة القادمين من خارج المملكة يأتي لأداء العمرة ويقول: أريد أن آخذ عن والدي أو والدتي عمرة، فيقول من أين أحرم؟ من التنعيم أو من الميقات؟","title":"من أين يُحْرِم الوافِد يريدُ عمرةً أخرى؟","answer":"الجواب: من الحِلّ، التنعيم، أو غيره من الحل، عرفات أو التنعيم أو الجعرانة؛ لأنه قد دخل بإحرام شرعي من الميقات، مثل ما أحرمت عائشة من التنعيم؛ لأنها قد دخلت بإحرامها الأول من الميقات. صار من أهل مكة، حكمه حكم أهل مكة، يحرمون من الداخل، يعني من خارج الحرم، لكن ما يلزم يرجع للميقات، من عرفات من الجعرانة من التنعيم، يسمونه العمرة الآن.","link":"https://binbaz.org.sa/fatwas/22862/من-اين-يحرم-الوافد-يريد-عمرة-اخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يأتي من خارج المملكة ويريد العمرة عن والديه فمن أين يحرم.mp3","categories":["المواقيت","الإحرام"]},{"id":3640,"question":"(الاشتراط) مقيّد بالخوف؟","title":"هل الاشتراط في الحج مقيّد بالخوف؟","answer":"الجواب: نعم؛ يخاف؛ إما مريض وإلا حرب.\nس: وإن اشترط من غير خوف هل ينفعه الشرط؟\nالشيخ: الظاهر العموم، مثل المرأة التي تخاف الحيض وأشباهه.","link":"https://binbaz.org.sa/fatwas/23825/هل-الاشتراط-في-الحج-مقيد-بالخوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/محلي حيث حبستني.. هل الاشتراط في الحج مقيد بالخوف.mp3","categories":["المواقيت","الإحرام"]},{"id":4641,"question":"يُؤخذ من هذا الحديث - حجّ عن نفسك، ثم حجّ عن شبرمة- تغيير النية بعد عقد نية الإحرام؟","title":"حكم تغيير النية بعد عقد نية الإحرام","answer":"الجواب: تقع عن نفسه.\nس: بعد عقد النية؟\nج: نعم، يكون عن نفسه، ينعقد عن نفسه، لا عن الشخص الذي أراد الحجَّ عنه؛ لأنه مأمورٌ أن يحجَّ عن نفسه قبل أن يحجَّ عن غيره.","link":"https://binbaz.org.sa/fatwas/24931/حكم-تغيير-النية-بعد-عقد-نية-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تغيير النية بعد عقد نية الإحرام.mp3","categories":["المواقيت","الإحرام"]},{"id":4642,"question":"الصبي يُلبي عنه وليُّه؟","title":"ما حكم إحرام وتلبية الصبي بالحج؟","answer":"الجواب: دون السبع يُلبي عنه وليُّه.\nس: بعد السبع يختلفون الصبيان في التَّمييز؟\nج: يُعلَّم إذا بلغ السبع، هذا محل الأمر بالصلاة والعبادة، يُعلَّم، وإذا ما لبَّى الأمر سهل، التلبية سنة، كذلك يلبس الإحرام.\n... يلبس، لا يحطّ عليه قميصًا ولا شيئًا.\nس: قال أبو حنيفة: لا يصح إحرامه ولا يلزمه شيء من محظورات الإحرام وإنما يحج به على جهة التدريب، هل هذا القول صحيح؟\nج: ليس بشيءٍ، أحاديث النبي ﷺ واضحة.","link":"https://binbaz.org.sa/fatwas/24932/ما-حكم-احرام-وتلبية-الصبي-بالحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إحرام وتلبية الصبي للحج.mp3","categories":["المواقيت","الإحرام"]},{"id":4643,"question":"لو أتى مكة ولم يكن اعتمر عمرةَ الإسلام ألا يلزمه الإحرام؟","title":"حكم من أتى مكة ولم يكن اعتمر عمرةَ الإسلام","answer":"الجواب: نعم يلزمه من الحلِّ، إذا كان أتاها ما نوى عمرةً؛ يُحرم من الحلِّ.","link":"https://binbaz.org.sa/fatwas/24933/حكم-من-اتى-مكة-ولم-يكن-اعتمر-عمرة-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يلزم الإحرام من أتى مكة ولم يكن اعتمر عمرةَ الإسلام.mp3","categories":["المواقيت","الإحرام"]},{"id":4644,"question":"مَن ذهب إلى جدة لعملٍ وهو ناوٍ العمرة؟","title":"إحرام مَن ذهب إلى جدة لعملٍ وهو ناوٍ العمرة","answer":"الجواب: يرجع إلى الميقات الذي مرَّ عليه، إن كان جاء من نجدٍ أو من الطائف لجدة لعملٍ وهو ناوٍ لعمرة يرجع إلى الميقات ويُحرم منه.  أما إذا ما نوى، جاء لحاجةٍ ثم طلع عليه في جدة قال: ما دام أني وصلتُ هذا المحلّ أود أن آخذ عمرةً، فيُحرم من مكانه.","link":"https://binbaz.org.sa/fatwas/24934/احرام-من-ذهب-الى-جدة-لعمل-وهو-ناو-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مَن ذهب إلى جدة لعملٍ وهو ناوٍ العمرة، فمن أين يحرم.mp3","categories":["المواقيت","الإحرام"]},{"id":4647,"question":"كراهة الإحرام بالحج قبل أشهر الحج للتنزيه؟","title":"ما حكم الإحرام بالحج قبل أشهر الحج؟","answer":"الجواب: الأقرب والله أعلم هو هذا؛ لأنها من السنة، ما قال: لا تفعلوا، قال: من السنة، يعني سنة النبي ﷺ.\nس: لكن تجاوز تحديد أشهر الحجّ؟\nج: الأقرب والله أعلم أنه للكراهة، إذا أحرم بالحجِّ قبل وقت الحجِّ يكون للكراهة، ويجعلها عمرةً، وهكذا لو أحرم بالحجِّ أو العمرة قبل الميقات يلزمه، وقد فعل ما لا ينبغي.\nس: يلزمه لكن هل يأثم؟\nج: الله أعلم، الأقرب عدم الإثم، وخالف السنة.","link":"https://binbaz.org.sa/fatwas/24937/ما-حكم-الاحرام-بالحج-قبل-اشهر-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإحرام بالحج قبل أشهر الحج.mp3","categories":["المواقيت","الإحرام"]},{"id":4653,"question":"هل ثبت في الغسل شيء غير أمر الحائض والنُّفساء؟","title":"ما دليل استحباب الغسل للمحرم؟","answer":"الجواب: حديث: \"تجرد لإهلاله واغتسل\"، حديث زيدٍ، وحديث ابن عمر: \"من السنة أن يغتسل\"، وفي حديث: أنَّ الحائض والنُّفساء اغتسلتا، وفي حديث جابرٍ: أنَّ أسماء بنت عميس ولدت محمد بن أبي بكر في ذي الحليفة، فأمرها النبيُّ أن تغتسل، وهكذا عائشة أمرها أن تغتسل، فإذا كانت الحائض تغتسل والنُّفساء وهما لا صلاةَ عليهما، ولا طهارةَ لهما، فغيرهما من باب أولى.","link":"https://binbaz.org.sa/fatwas/24943/ما-دليل-استحباب-الغسل-للمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ثبت في الغسل شيء غير أمر الحائض والنُّفساء.mp3","categories":["المواقيت","الإحرام"]},{"id":4657,"question":"الذي لا يخاف مرضًا ما يشترط؟","title":"هل يشترط من لا يخاف مرضًا في الحج؟","answer":"الجواب: الأفضل عدم الاشتراط؛ لأنَّ الرسول لم يشترط عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24948/هل-يشترط-من-لا-يخاف-مرضا-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشترط من لا يخاف مرضًا أو غيره في الحج.mp3","categories":["المواقيت","الإحرام"]},{"id":4663,"question":"مَن أتى بالحجِّ مُفردًا، وأراد عمرةً بعد الحجِّ، يأتي بها من التنعيم أم من المواقيت؟","title":"ما حكم من أتى بالحجِّ مُفردًا وأراد عمرةً بعده؟","answer":"الجواب: من التنعيم مثلما فعلت عائشةُ ويكفي، يعني من الحلِّ.","link":"https://binbaz.org.sa/fatwas/24955/ما-حكم-من-اتى-بالحج-مفردا-واراد-عمرة-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أتى بالحجِّ مُفردًا، وأراد عمرةً بعد الحجِّ.mp3","categories":["المواقيت","الإحرام"]},{"id":5215,"question":"يقول السائل: هل يجوز لي أن أتمتع في اليوم الثامن؟","title":"هل يجوز للحاج التمتُّع في اليوم الثامن؟","answer":"الجواب: نعم، إذا دخلت البلد، وجئتَ من بلدك الثامن وأنت مُلبٍّ بالعمرة؛ تطوف وتسعى، وإن كنتَ مُلبيًا بالحج تجعلها عمرةً، تنويها عمرة، فتطوف وتسعى وتُقصّر وتحلّ كما أمر النبيُّ أصحابَه، ثم تُلبي وتغتسل بعد ذلك، تستريح وتغتسل وتتطيَّب، ثم تُلبي بالحج، هذا هو الأفضل.","link":"https://binbaz.org.sa/fatwas/30159/هل-يجوز-للحاج-التمتع-في-اليوم-الثامن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 191.mp3","categories":["المواقيت","الإحرام"]},{"id":5227,"question":"هذا سائل يقول: إنَّ بعضًا من طلبة العلم يقولون: إنَّ مَن أحرم بحجةٍ أو عمرةٍ قبل الميقات فإن ذلك الإحرام لا ينعقد، وعليه فيكون قولهم قطعًا بعدم انعقاد الإحرام تبعًا لابن حزم، فماذا نقول لهؤلاء ونرد عليهم به؟ جزاكم الله خيرًا.","title":"ما حكم من أحرم بحجةٍ أو عمرةٍ قبل الميقات؟","answer":"الجواب: الصواب الذي عليه جمهورُ أهل العلم أنه ينعقد، ولكن ترك الأفضل، فالنبي ﷺ لما وقَّت المواقيت قال: هُنَّ لهُنَّ، ولمَن أتى عليهنَّ من غير أهلهنَّ ممن أراد الحجَّ أو العمرة فالسُّنة له أن يُحرم من الميقات، فلو أحرم من غير الميقات انعقد عند أهل العلم، ولكنه ترك الأفضل، فلو أحرم صاحبُ الطائف من بيته، أو صاحبُ المدينة من بيته، أو صاحبُ الرياض من بيته؛ أجزأ، ولكن ترك ما هو السنة، وهو ألا يُحرم إلا من الميقات، وقصاراه أنه شدَّد على نفسه، والله جلَّ وعلا يسَّر له الأمر، وجعل الإحرام من الميقات حتى يكون هذا أيسر عليه، وحتى لا تطول عليه المدَّة في الإحرام، فإذا شدد على نفسه وأحرم قبل ذلك -إمَّا جهلًا وإمَّا لقصدٍ آخر- فإنَّ إحرامه ينعقد، وقصاراه أنه فعل مكروهًا، أو ترك ما هو الأفضل، وأما القول بأنه لا ينعقد فهو قولٌ ضعيفٌ وليس بشيءٍ.","link":"https://binbaz.org.sa/fatwas/30171/ما-حكم-من-احرم-بحجة-او-عمرة-قبل-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 261.mp3","categories":["المواقيت","الإحرام"]},{"id":5250,"question":"هل يقع من أهل مكة تمتع وقران؟","title":"ما حكم حج التمتع والقران لأهل مكة؟","answer":"الجواب: نعم، لا بأس، لكن ليس عليهم هَدْي التمتع والقران، فلهم أن يمتعوا بالعمرة في أشهر الحج، ولهم أن يقرنوا بينهما، لكن الأفضل لهم الحج المفرد؛ لأنَّ الله وسَّع لهم العمرة، متى شاءوا اعتمروا، فلو اعتمروا في أشهر الحج فلا بأس.","link":"https://binbaz.org.sa/fatwas/30665/ما-حكم-حج-التمتع-والقران-لاهل-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 737.mp3","categories":["المواقيت","الإحرام"]},{"id":5270,"question":"رجل أحرم من الميقات وهو لابس المخيط، لما وصل إلى مكة مرض ورجع إلى بلاده غير معتمر، في هذه الحال ماذا عليه؟","title":"حكم من أحرم من الميقات ورجع لبلده ولم يعتمر","answer":"الجواب: لابس المخيط، ما عنده إحرام؟ س: ما عنده إحرام أو أنه تكاسل؟ ج: المقصود عليه فدية، عليه إطعام ستة مساكين، أو صوم ثلاثة أيام، أو ذبح شاة، أحد الثلاثة في لبس المخيط مثلما عليه لو حلق رأسه، أما إذا رجع ولم يحل إحرامه عليه أن يرجع إلى مكة. س: ما اعتمر، أحسن الله إليك؟ الشيخ: ما أحرم تقول؟ س: هو أحرم لكن مرض ورجع؟ الشيخ: إن كان عمل عمل المحصر لا بأس، إن كان نحر وقصر وحلّ على أنه محصر لا بأس؛ لأن مرضه يكون إحصارًا فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196] إذا أحصر الإنسان بالمرض أو بالعدو أو بذهاب النفقة يكون محصرا، والمحصر ينحر شاة، أو سُبع بدنة، أو سُبع بقرة بنية الإحصار، ثم يحلق رأسه أو يقصر ويحل، والحمد لله؛ لأن الله قال: فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196] إذا لم يشترط، وإذا اشترط ما عليه شيء. س: إذا كان ما اشترط يا شيخ؟ ج: عليه أن يعمل عمل الإحصار، يهدي ثم يقصر ويحلق. س: حتى وإن وصل إلى الرياض يقصر شعره في الرياض؟ ج: نعم نعم، في محله الذي وصل فيه.[1]","link":"https://binbaz.org.sa/fatwas/30877/حكم-من-احرم-من-الميقات-ورجع-لبلده-ولم-يعتمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/wazayif ramadan 013.mp3","categories":["المواقيت","الإحرام"]},{"id":5340,"question":"إذا كانت المرأة عليها الدورة الشهرية وتريد العمرة وهي خارج مكة هل تستطيع أن تحرم من الميقات ومن ثم تطوف إذا طهرت؟","title":"حكم إحرام الحائض من الميقات وطوافها إذا طَهُرت","answer":"الجواب: نعم، تُحْرِم ولو هي في الحيض، تُحْرِم من الميقات وإذا طَهُرت تطوف وتسعى، تبقى في بيتها حتى تَطهُر، وإذا طَهُرت اغتسلت وطافت، والحمد لله، وهكذا النفساء، إذا أحرمت وهي نفساء وبقيت على إحرامها حتى طهرت كذلك.[1]","link":"https://binbaz.org.sa/fatwas/31013/حكم-احرام-الحاىض-من-الميقات-وطوافها-اذا-طهرت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 061.mp3","categories":["المواقيت","الإحرام"]},{"id":5361,"question":"رجل نوى العمرةَ ثم أحرم من الميقات، وبعد دخول الحرم وجد الزِّحام فرجع إلى منزله ولبس ملابسه ولم يعتمر في رمضان الماضي، ماذا عليه الآن، علمًا بأنه غير مُتزوج؟","title":"ما حكم من أحرم ولم يعتمر بسبب الزحام؟","answer":"الجواب: عليه أن يُكمل العمرة، ما زال مُحرمًا، وعليه أن يذهب فيطوف ويسعى ويُقصر ويحلّ، وإذا كان جاهلًا ما عليه شيء من جهة لبس الثياب؛ من أجل جهله.[1]","link":"https://binbaz.org.sa/fatwas/31065/ما-حكم-من-احرم-ولم-يعتمر-بسبب-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima004.mp3","categories":["المواقيت","الإحرام"]},{"id":6180,"question":"نويت الحج، أو العمرة، وتحركت من الرياض في أيام الحج، وأراد الذهاب إلى جدة لمهمة عمل، فمن أين أحرم؟","title":"حكم من قصد الحج أو العمرة وتعدى الميقات ولم يحرم","answer":"الجواب: إذا كان الإنسان أراد الحج، أو العمرة، وذهب إلى جهة مكة؛ فعليه الإحرام من الميقات الذي يمر عليه، إن كان من الرياض، أو الطائف، أو ما دونهما، أو ما هو غير ذلك يمر على ميقات أهل نجد، ويحل منه، وهو السيل المعروف، وهذا المحرم المعروف يحرم من أحدهما. فإن كان من جهة أخرى كما جاء من طريق المدينة؛ يحرم من ميقات المدينة، أو جاء من طريق اليمن؛ يحرم من ميقات اليمن يلملم، أو جاء من طريق الشام، أو من مصر جاء من طريق البحر؛ يحرم من ميقات مصر، والشام، رابغ الجحفة، أو جاء من طريق العراق؛ يحرم من طريق العراق، وهو ... المعروفة، أو من  السيل ميقات أهل نجد كما هو معروف الآن.  أما من جاء إلى جدة ما عنده نية عمرة، جاء إلى جدة لعمل، ثم طرأ عليه أن يعتمر؛ يحرم من جدة من مكانه ، فإن النبي -عليه الصلاة والسلام- قال: لما وقت المواقيت قال: هن لهن، ولمن أتى عليهن من غير أهلهن، ممن أراد الحج، والعمرة، وكان دون ذلك أي دون المواقيت فمهله من حيث أنشأ حتى أهل مكة من مكة.  فإذا جاء جدة، ما قصد العمرة، جاء إليها لعمل، ثم بدا له أن يعتمر، يحرم من جدة، أو بدا له أن يحج، يحرم من جدة، أما إذا جاء من الرياض، أو جاء من اليمن، أو جاء من أي مكان ... المواقيت قصده الحج، أو قصده العمرة، أو قصده يمر جدة، ويعتمر فهذا يحرم من الميقات إن كان من طريق المدينة، فمن ميقات المدينة، إذا كان من طريق الطائف فمن ميقات الطائف.. جاء من طريق اليمن يحرم من يلملم.\n...... أسئلة...","link":"https://binbaz.org.sa/fatwas/1639/حكم-من-قصد-الحج-او-العمرة-وتعدى-الميقات-ولم-يحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_530.mp3","categories":["الإحرام","المواقيت"]},{"id":6182,"question":"كيف يحرم في الطائرة؟","title":"كيفية إحرام من كان على الطائرة أو السفينة","answer":"الجواب: في الطائرة يحرم في الجو نعم، وهكذا في البحر، إذا وازى المواقيت، تحرم من البحر في الباخرة، أو السفينة، وإذا كان في الجو يتحرى الميقات، ويحرم قبل أن يصله، أو يحرم في مطار من بلده إذا كان يخشى أن يلتبس عليه الأمر لا بأس إذا تقدم بإحرامه لحاجة لا بأس. ولكن في الغالب أنه يتيسر له أن يستعد في بلاده، يغتسل إذا تيسر، يتطيب، يلبس الإزار، والرداء، ويكون في الطائرة مستعدًا فإذا صار بينه وبين جدة نحو نصف ساعة؛ يحرم؛ لأنه حينئذ قد وزاى الميقات إذا كان من طريق الطائرة. أما إذا كان من طريق المدينة معروف أتى أهل المدينة أحرم، وإذا كان من طريق البحر من طريق الساحل إذا وازى رابغ، أو من طريق مصر، أو الشام، أحرم وهو في الجو، أو قبله بيسير حتى يحتاط، ويحرم قبل ذلك، فإنه حين يقوم من المطار، ويمشي قليلًا تسير الطائرة قليلًا يحرم احتياطًا لا بأس، أما تأجيل الإحرام إلى أن يأتي جدة لا.","link":"https://binbaz.org.sa/fatwas/1640/كيفية-احرام-من-كان-على-الطاىرة-او-السفينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_531.mp3","categories":["المواقيت","الإحرام"]},{"id":6539,"question":"ذهبت إلى العمرة، واعتمرت من جدة، فهل هناك علي هدي؟","title":"حكم من أحرم للعمرة من جدة","answer":"الجواب: إذا كنت من أهل جدة يكفي، أما إذا كنت جئت من مكان آخر، من الرياض، أو من الطائف، وأنت تقصد العمرة، ولكن ما أحرمت إلا من جدة، وتجاوزت الميقات؛ فعليك دم عن ترك الميقات، إذا كنت جئت من مكان بعيد عن جدة، مثلًا جئت من الطائف، أو جئت من رابغ، وأنت من أهل رابغ، وما أحرمت من رابغ، وجئت العمرة، وأنت في رابغ، ولا أحرمت منه، يكون عليك ذبيحة تتميمًا لعمرتك، وجبرًا لها.  أما إذا كنت من أهل جدة؛ فلا بأس، أو كنت جئت جدة ما نويت شيئًا، سافرت من الرياض، أو من المدينة، أو من غيرها إلى جدة، ما عندك نية، ما عندك نية عمرة، ما طرأ عليك عمرة، فلما صرت في جدة؛ طرأ عليك أخيرًا، وبدا لك أخيرًا أن تعتمر؛ فلا بأس تحرم من جدة، ولا شيء عليك؛ لأنك ما نويت العمرة إلا منها؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/2376/حكم-من-احرم-للعمرة-من-جدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_910.mp3","categories":["المواقيت","الإحرام"]},{"id":6675,"question":"مسافر أقام في الرياض، ونوى العمرة، وأحرم من جدة، فما حكم الإسلام؟","title":"حكم من نوى العمرة وجاوز الميقات ولم يحرم","answer":"الجواب: إذا توجه من الرياض إلى جدة للعمرة يحرم من الميقات هذا الواجب، إذا جاء ميقات ... أو قبله بيسير يتحرى، ويحرم، يستعد لهذا في بيته، يلبس الإزار، والرداء ، يتطيب لا بأس، أو  في الطائرة يتطيب، فكل ذلك جائز، لكن الإحرام هو أن ينوي الدخول في العمرة، أو يلبي، هذا عند قرب الميقات وعند ... الميقات يلبي، ويقول: اللهم لبيك عمرةن وينوي بقلبه، هذا هو المشروع، هذا الواجب، ولا يترك حتى يأتي جدة لا، وإذا فعل؛ فعليه دم إذا لم يحرم إلا من جدة، وهو جاء من الرياض، أو من غير الرياض من جهة الشرق، ومر على الميقات، ولم يحرم؛ يكون عليه دم، أو جاء من المدينة ولم يحرم إلا من جدة وهو قاصد العمرة، أو الحج؛ يكون عليه دم. السؤال: إذا كان جاء للعمل يريد عملًا، وأراد أن ينتهز الفرصة للعمرة؟ الجواب: بعد عمله ؟ ما أراده الآن؟ السؤال: نعم؟ الجواب: إذا أرادها بعد العمل ما في بأس ، إذا كان عمله في جدة، وينوي إذا فرغ من العمل أن يعتمر؛ لا بأس، أما أنه ينوي في الرياض أنه يعتمر فهذا لا بد يحرم من الميقات.  السؤال: لكن إذا كان يبغى إنه يروح جدة، ثم يحرم من الميقات جائز هذا؟ الجواب: ما في بأس.. ثم  يعود للميقات.","link":"https://binbaz.org.sa/fatwas/2553/حكم-من-نوى-العمرة-وجاوز-الميقات-ولم-يحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1048.mp3","categories":["المواقيت","الإحرام"]},{"id":7240,"question":"شخص سافر أيام الحج من الرياض إلى المدينة المنورة، وليس هو محرم، ثم سافر من المدينة إلى جدة، ومكث فيها خمسة عشر يومًا وهو مسافر بالطائرة من مكان سكنه بالرياض، ولم يكن قصده الحج، ولكن للزيارة، ولما حضرت أيام الحج؛ أراد أن يحج، وحج، وكمل حجه، فهل يلزمه الهدي؛ لأنه من سكان الرياض، وأحرم من ميقات جدة، وهل جدة من المواقيت؟","title":"حكم من جاء إلى جدة للزيارة ثم أحرم منها للحج","answer":"الجواب:\n\nلا ما يلزمه شيء ما دام جاء إلى جدة ما قصد حجًا ولا عمرة، جاء للزيارة ثم صادف الحج، وأحرم من جدة بالحج فقط بدون عمرة؛ ما عليه فدية.\n\nأما إذا أحرم بالعمرة من جدة، وتمم العمرة، ثم أحرم بالحج، أو أحرم بهما جميعًا من جدة؛ فعليه الهدي؛ لأنه متمتع، أما إذا أحرم بالحج مفردًا من جدة، صادف الحج وهو فيها، وأحرم منها؛ فلا بأس عليه، يكون مفردًا.","link":"https://binbaz.org.sa/fatwas/3293/حكم-من-جاء-الى-جدة-للزيارة-ثم-احرم-منها-للحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1618.mp3","categories":["المواقيت","الإحرام"]},{"id":8848,"question":"أختنا من الرياض السائلة أم محمد بعثت برسالة تقول: إننا من سكان مدينة الرياض، وقد اعتدنا في كل عام الذهاب في رمضان للعمرة، وقد حدث لنا أننا في ثلاث سنوات كنا إذا ذهبنا للعمرة إلى مكة نصل إلى جدة ولا نذهب رأسًا إلى مكة، بل ننام في جدة، وفي اليوم الثاني نذهب مكة أي: نعتمر من جدة، فما حكم عمرتنا في تلك السنوات الثلاث؛ لأننا لم نذهب إلى مكة بل نبات في جدة ونعتمر منها؟ والسؤال الثاني: إذا كان علينا شيء وجهونا جزاكم الله خيرًا؟","title":"حكم من نوى العمرة وتجاوز الميقات دون أن يحرم","answer":"الجواب: إذا كان إحرامكن بالعمرة من جدة وأنتن جئتن من الرياض للعمرة فعليكن دم، كل واحدة عليها دم في جميع العمر الثلاث، تذبح في مكة للفقراء والمساكين؛ لأن الواجب عليكن الإحرام من الميقات ميقات الطائف وادي قرن، وليس لكن أن تجاوزن ذلك إلى جدة من غير إحرام، بل يجب الإحرام من الميقات.\nوإذا قصدتن جدة وبتن فيها فلا بأس وأنتن محرمات إذا بتن في جدة ثم ذهبتن إلى مكة فلا بأس، أما تجاوز الميقات والإحرام من جدة هذا لا يجوز، والذي فعل ذلك عليه الفدية، عليه ذبيحة تذبح في مكة للفقراء جبرًا للعمرة؛ لأن عمرته صارت ناقصة لإحرامه من جدة صارت ناقصة.\nلكن لو رجع إلى الميقات وأحرم من الميقات ولم يحرم من جدة أجزأه ذلك، لما تنبه وتذكر رجع قبل أن يحرم إلى الميقات وأحرم منه فلا بأس، لكن الواجب عليه أولًا إذا مر بالميقات أن يحرم من الميقات؛ لأنه جاء للعمرة فليس له تجاوزه إلا بإحرام، هذا هو الواجب، ولو أقام في جدة ولو بات فيها وهو محرم لا يضره ذلك.\nأما إذا تجاوز الميقات بغير إحرام ثم يحرم من جدة هذا هو الذي لا يجوز، لكن من فعل ذلك فعليه فدية، وهي ذبيحة تذبح في مكة للفقراء جبرًا للعمرة.\nالمقدم: جزاكم الله خيرًا، هل من الممكن -سماحة الشيخ- السؤال عن أولئك الذين يجوز لهم الإحرام من جدة ليعرف من هو ضدهم؟\nالشيخ: يجوز لأهلها أن يحرموا منها، الساكنين فيها والمقيمين فيها للعمل، إذا أرادوا العمرة يحرموا من جدة لا بأس، كما يحرم الذي في بحرة من بحرة، والذي في أم السلم من أم السلم، والذي في ... من ...؛ لقول النبي ﷺ لما وقت المواقيت قال: هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد الحج والعمرة، ومن كان دون ذلك فمهله من أهله -حتى قال-: حتى أهل مكة من مكة وفي اللفظ الآخر: ومن كان دون ذلك فمهله من حيث أنشأ يعني: من حيث أنشأ الإحرام، فهؤلاء الذي في جدة مستوطنين أو بها وهم غير مستوطنين بل مقيمون للعمل إذا أرادوا الحج أو العمرة أحرموا من مكانهم.\nوهكذا لو أن إنسانًا جاء من الرياض أو من جدة أو من غيرهما من ... من المدينة أو من غيرهما لجدة لا لقصد العمرة ولا لقصد الحج، بل جاء من الرياض أو من المدينة أو من الشام أو من مصر أو غير ذلك إلى جدة لحاجة خاصة للعمل أو لزيارة قريب، أو لعمل تجاري، أو ما أشبه ذلك ثم بدا له أن يحرم، بدا له أن يحج بدا له أن يعتمر حين وصل إلى جدة فهذا يحرم من جدة كالمقيم بها؛ لأنه حين مر المواقيت لم ينو العمرة ولا الحج، وإنما أنشأ ذلك من نفس جدة، فهذا الذي أنشأ الحج أو العمرة من جدة يحرم من جدة كالمقيمين بها، نعم.\nالمقدم: جزاكم الله خيرًا، إذًا والحالة هذه جدة ليست بميقات سماحة الشيخ؟\nالشيخ: ...ليست ميقاتًا للناس، لكنها ميقات لأهلها والمقيمين فيها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7003/حكم-من-نوى-العمرة-وتجاوز-الميقات-دون-ان-يحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16605.mp3","categories":["المواقيت"]},{"id":9043,"question":"المستمعة صالحة محمد علي أبو حسين من مكة المكرمة حي الزاهر، بعثت برسالة للبرنامج تقول فيها: بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله وبركاته، إنني من المستمعات المعجبات ببرنامج نور على الدرب، لما فيه من النصائح القيمة، وأود أن أعرض أسئلتي على الأفاضل العلماء، في برنامج نور على الدرب، أرجو الإجابة عليها.السؤال الأول تقول فيه: من أين يحرم من هو بمكة؟ أفيدونا أفادكم الله.","title":"ميقات أهل مكة","answer":"الجواب: الذي في مكة يحرم من الحل، هذا هو السنة، يعني: يحرم من التنعيم أو من الجعرانة أو من غيرهما كعرفة أو جدة، المقصود يخرج من الحرم، ويحرم من وراء الأميال خارج الحرم، والحجة في ذلك ما ثبت عن النبي ﷺ أنه أمر عائشة لما أرادت العمرة أمرها أن تخرج إلى الحل، أمر عبد الرحمن بن أبي بكر أخاها، أن يخرج بها إلى الحل، تحرم من الميقات الذي هو الحل من التنعيم، أحرمت من التنعيم رضي الله عنها، وهو أدنى الحل إلى مكة، وهكذا غيرها من الناس الذين في مكة إذا أراد العمرة يخرج، وهذا الذي عليه عامة العلماء وجمهورهم أنه يخرج من مكة ولا يحرم من مكة، بل يحرم بالعمرة من الحل ثم يدخل فيطوف ويسعى ويقصر ويحل، أو يحلق ويحل، والمرأة ليس لها إلا التقصير، تطوف وتسعى وتقصر من رأسها وليس لها الحلق.","link":"https://binbaz.org.sa/fatwas/7202/ميقات-اهل-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22403.mp3","categories":["المواقيت"]},{"id":9045,"question":"السؤال الثاني والأخير في رسالة المستمع: هشام محمد يوسف المصري ، من المدينة المنورة، يقول فيه: ما حكم من تجاوز الميقات دون إحرام، وماذا عليه أن يفعل حتى يكون حجه صحيح؟ أفيدونا أفادكم الله.","title":"بيان القول فيمن جاوز الميقات دون أن يحرم","answer":"الجواب: إذا تجاوز المسلم الميقات من دون إحرام وهو مكلف.. بالغ عاقل، هذا فيه تفصيل:\nإن كان أراد الحج أو العمرة، فعليه أن يرجع إلى الميقات ليحرم منه، يعني: الميقات الذي مر به، فإن كان جاء من طريق المدينة عليه أن يرجع إلى المدينة فيحرم من المدينة، وإن كان جاء من طريق الشام أو مصر ولم يأت من طريق المدينة بل من جهة الساحل فإنه يحرم من الجحفة من رابغ، وهكذا من جاء من اليمن يحرم من ميقات اليمن، ومن جاء من نجد والطائف ونحوها أحرم من ميقات الطائف، من السيل -وادي قرن- لقول النبي صلى الله عليه وسلم لما وقت المواقيت: هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد الحج والعمرة، فإن أحرم بعدما جاوزها ولم يعد إليها فعليه دم يذبح في مكة للفقراء، إذا جاوز الميقات بأن أتى من المدينة وجاوز ميقات المدينة وأحرم من جدة -مثلاً- فإن عليه دماً يذبح في مكة للفقراء والمحاويج، وهكذا لو أتى من الشام أو مصر ولم يحرم إلا من جدة وهو قاصد الحج أو العمرة فإن عليه دماً يذبح في مكة للفقراء والمحاويج.\nأما إن كان حين مر بالميقات ما قصد حج ولا عمرة، إنما جاء لحاجة مثل التجارة في مكة أو لزيارة بعض أقاربه، أو لأي أمر آخر ليس قصده الحج والعمرة، فهذا لا يلزمه الإحرام على الصحيح من أقوال العلماء لا يلزمه الإحرام، ولكن يستحب له أن يحرم بالعمرة؛ لأن النبي عليه السلام قال: هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد الحج والعمرة فمفهوم ذلك أن الذي ما أراد الحج العمرة ليس عليه إحرام، ويدل على هذا أيضاً أنه ﷺ لما دخل مكة لغزوها عام الفتح لم يحرم بل دخلها وعلى رأسه المغفر؛ لأنه لم يأت للحج ولا للعمرة إنما أتى لافتتاحها وتطهيرها من الشرك، والله ولي التوفيق. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7208/بيان-القول-فيمن-جاوز-الميقات-دون-ان-يحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22407.mp3","categories":["المواقيت"]},{"id":9397,"question":"من دولة الكويت هذه رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من هناك يقول: المرسل عثمان عبدالرحمن، أخونا يقول: توجهت -بحمد الله- من الكويت إلى جدة لأداء العمرة وذلك عن طريق المدينة بالطائرة، وعندما أقلعت الطائرة من المدينة متجهة إلى جدة أعلن قائد الطائرة بأن الذين يريدون أداء العمرة عليهم البدء بلبس لباس الإحرام، وفعلًا توجهت إلى الحمام لتغيير ملابسي واستغرقت ما يقارب ثلث ساعة تقريبًا، وبعد أن خرجت سألت أحد المضيفين هل وصلنا إلى الميقات؟ فأجاب بأننا قد تجاوزنا الميقات منذ فترة، ومعنى هذا بأنني قد تجاوزت الميقات وأنا أحاول أن أتمكن جيدًا من لبس الإحرام، وللعلم فإني قد نسيت أن أنزع طاقية الرأس حتى قبل خروجي بقليل من الحمام، وكذلك فإني قد نسيت أن أقول: لبيك عمرة بعد خروجي مباشرة، ولكني قلتها بعد فترة، مع العلم بوجود نية الدخول في النسك لدي، وقد أتممت باقي أركان العمرة بعد ذلك فهل علي شيء في النواقص التي ذكرت، أفتوني جزاكم الله خيرًا؟","title":"حكم من تجاوز الميقات قبل أن ينوي الدخول في العمرة","answer":"الجواب: إذا كنت لم تنو العمرة إلا بعدما جاوزت الميقات فعليك دم، ذبيحة واحدة تذبح في مكة للفقراء؛ لأن الواجب هو الإحرام من ميقات المدينة، وقد تأخرت كثيرًا كما ذكرت عمن أخبرك، وأنك تجاوزت الميقات، فالواجب عليك أن تذبح رأسًا من الغنم إما جذع ضأن أو ثني من المعز كالضحية ونحوها في مكة للفقراء، لما أخللت به من الميقات.\nأما الطاقية فإذا كنت أزلتها لما خرجت قبل أن تنوي الدخول في العمرة فلا شيء عليك، أو تركتها ناسيًا فلا شيء عليك، أما إن تعمدت بقاءها على رأسك بعد الإحرام وأنت تعلم أن هذا محرم عليك وذاكر لذلك فعليك فدية، وهي إطعام ستة مساكين أو صيام ثلاثة أيام أو ذبح شاة أحد الثلاثة، إما هذا وإما هذا وإما هذا، إذا كنت تعمدت بقاءها بعد الإحرام، أما إن كانت بقيت عليك نسيانًا أو جهلًا فلا شيء عليك. نعم.\nالمقدم: شيخ عبد العزيز! الفدية الأولى التي تفضلتم بذكرها هل هي لتجاوزه الميقات أو لأنه لم ينو إلا متأخرًا؟\nالجواب: لتجاوزه الميقات قبل أن ينوي الدخول في النسك.\nالمقدم: قبل أن ينوي الدخول في النسك؟\nالشيخ: في العمرة. نعم.\nأما لفظ التلبية ولو تأخر لفظ التلبية، لكن المقصود النية نية دخوله في النسك إذا كان بعدما جاوز الميقات بمسافة فإنه عليه الفدية، أما إذا كان في حدود الميقات فلا بأس ولا شيء عليه.\nالمقدم: إذًا: نية الدخول في النسك غير نية السفر للإتيان بعمرة؟\nالشيخ: لا، نية الدخول هي الإحرام.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7562/حكم-من-تجاوز-الميقات-قبل-ان-ينوي-الدخول-في-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_188/18803.mp3","categories":["المواقيت"]},{"id":9596,"question":"السؤال الثاني في رسالة الإخوة السودانيين المقيمين بالمملكة يقولون فيه: نويت الذهاب لمقابلة والدتي القادمة من خارج المملكة للحج، فهل يجوز لي أن أنوي بعد ذلك أداء الفريضة معها مع أن النية الأولى هي لمقابلة الوالدة وليس لأداء الفريضة أفيدونا أفادكم الله؟","title":"حكم من اجتاز الميقات دون نية الحج ثم نوى بعد ذلك","answer":"الجواب: إذا توجه الإنسان إلى جدة مثلًا في قصد مقابلة الوالدة أو غيرها من الحجاج والسلام عليها ولم ينو الحج ولا عمرة ولا شيء ثم بدا له أن ينوي الحج معها وأن يحرم من جدة مثلًا ولا حرج عليه في ذلك؛ لأنه ما نوى إلا في جدة، أما إذا كان نوى الحج قبل أن يأتي جدة ونوى العمرة فعليه أن يحرم ميقات بلده إذا كان بلده من طريق المدينة يحرم من المدينة من طريق الساحل يحرم من الجحفة رابغ من طريق الطائف يحرم من ميقات الطائف وهكذا، ...... ..... جدة ولا يريد حجًا ولا عمرة وإنما جاء ليقابل بعض القادمين، ثم بدا له أن يحرم فلا بأس يحرم في جدة ولا حرج عليه. نعم.","link":"https://binbaz.org.sa/fatwas/7762/حكم-من-اجتاز-الميقات-دون-نية-الحج-ثم-نوى-بعد-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19306.mp3","categories":["المواقيت"]},{"id":9849,"question":"يسأل أخيراً ويقول: أنا مقيم في جنوب المملكة، وقد توجهت إلى مكة المكرمة لأداء العمرة فتجاوزت الميقات دون إحرام، وأحرمت من جدة، فما الحكم في ذلك؟ بارك الله فيكم.","title":"حكم من تجاوز الميقات دون إحرام","answer":"الجواب: إذا كنت حين جاوزت الميقات ناوياً العمرة، فإن عليك دماً، عن ترك بعض الميقات؛ لأن جدة ليست ميقاتاً لك، وإنما هي ميقات لأهلها والمقيمين فيها.\nأما إذا كنت ما نويت العمرة إلا في جدة، وحين جاوزت الميقات لم تنو العمرة فلا شيء عليك، والواجب على كل مسلم إذا أراد العمرة أو الحج يحرم من الميقات الذي يمر عليه، فمن طريق المدينة يحرم من المدينة من ميقات المدينة، إن كان من طريق الساحل جاء من الشام أو مصر أحرم من رابغ، إن كان من اليمن أحرم من ميقات اليمن كيلملم، وإن كان من طريق نجد أو الطائف أحرم من ميقات الطائف، وادي قرن، هذا هو الواجب على المؤمن، ولا يتجاوز المواقيت بغير إحرام، أما إذا كان ما أراد حجاً ولا عمرة، وإنما جاء إلى جدة أو إلى مكة لحاجة لعمل لزيارة قريب أو صديق، ما قصد حجاً ولا عمرة، فهذا لا يلزمه الإحرام، ومتى أراد العمرة وأحرم من جدة أو من التنعيم خارج الحرم فلا بأس، في العمرة يعني، أما الحج فيحرم من حيث شاء، متى عزم على الحج يحرم ولو من مكة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8025/حكم-من-تجاوز-الميقات-دون-احرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26213.mp3","categories":["الإحرام","المواقيت"]},{"id":10011,"question":"من قرية الشبيطة بالجمهورية العربية اليمنية قضاء زبيدي المستمع: أحمد عمر الشجاني بعث يقول: أنا شاب مسلم من الجمهورية العربية اليمنية، لقد حجيت عدة حجات والحمد لله، ولكنني غير متعلم -رجل أمي- ولقد حجيت لوالدي من ضمن الحجات المتكررة التي وفقني الله بها في هذا البلد الأمين، وأفيدكم بأنني لم أفد بأي ذبيحة في الحج؛ بحيث أنني كنت لا أعرف ما معنى الذبيحة، هل أنا ملزم بها أم لا، ولكن عندما تفهمت من المرشدين والخطباء فكرت في هذا الأمر، وقررت أن أسأل سماحتكم ماذا علي في ذلكم التقصير، أفيدوني أثابكم الله؟ثم إنني عندما أقدم من اليمن لا أحرم من الميقات المخصص لأهل اليمن وهو وادي يلملم؛ بحيث أنني أتعدى هذا الميقات وعندما أصل مدينة جدة أحرم منها وأذهب إلى مكة المكرمة، ولكنني فهمت بأنه يلزم الإحرام من الميقات الذي يحرم فيه أهل اليمن، فقررت أن أسأل سماحتكم ماذا يلزمني أيضًا في ذلك، جزاكم الله خيرًا؟","title":"حكم من لم يحرم من ميقات بلده جاهلًا","answer":"الجواب: يلزمك عن ترك الإحرام من الميقات دم يذبح في مكة، عن كل سفرة أخذت فيها عمرة أو حج ولم تحرم من ميقات اليمن، عليك أن تذبح عن كل واحدة ذبيحة في مكة للفقراء مع التوبة والاستغفار.\nأما الفدية فإن كنت إذا قدمت مكة للحج تحرم بالحج مفردًا وتبقى على إحرامك ولم تأت بعمرة فليس عليك فدية، أما إذا كنت حين حججت في حجاتك تحرم بالعمرة بعد رمضان ثم تحج فعليك فدية عن جميع الحجات التي وقع فيها عمرة بعد رمضان، كل حجة فيها عمرة بعد رمضان عليك دم عنها يذبح في مكة، وتأكل منه وتطعم.\nأما الحجات التي ليس فيها عمرة بل تأتي تحرم من الميقات بحج مفرد وتبقى على إحرامك حتى تؤدي الحج هذا ليس عليك فيه فدية، والحمد لله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8180/حكم-من-لم-يحرم-من-ميقات-بلده-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33115.mp3","categories":["المواقيت"]},{"id":10151,"question":"أحد الإخوة المستمعين بعث يقول: أنا مصري ومقيم في المملكة لي جمع من الأسئلة، أسأل أولاً هذا  لقد حضرت والدتي لأداء العمرة في شهر رمضان دون أن تحرم من الميقات، ثم أقامت ثلاثة أيام في جدة قبل أن تذهب إلى مكة لأداء العمرة، فهل عليها دم، أم لا؟","title":"حكم من قدم للعمرة وتجاوز الميقات ولم يحرم","answer":"الجواب: هذا فيه تفصيل: إذا كانت قدمت من مصر للعمرة فالواجب إحرامها من الميقات من ميقات أهل مصر وهو الجحفة -رابغ- إذا وازنته في البحر أو في الجو تحرم، وإن كان من طريق البر إذا وصلت إلى الجحفة من طريق الساحل تحرم وإن كان من طريق المدينة تحرم من ميقات المدينة هذا الواجب عليها، فإذا أحرمت من جدة يكون عليها دم يذبح في مكة للفقراء، وشاة تجزئ الضحية أو سبع بدنة أو سبع بقرة هذا هو الواجب عليها عن ترك الميقات، شاة واحدة يعني: جذع ضأن أو ثني معز يذبح في مكة للفقراء، أوسبع بدنة أوسبع بقرة يذبح في مكة للفقراء، هذا إذا كانت نوت العمرة من بلادها من مصر مثلاً، لكن ما أحرمت إلا من جدة تساهلت أو جهلت فهذا إحرامها صحيح من جدة وعمرتها صحيحة لكنها ناقصة تجبر بدم لأنها تركت الميقات الشرعي الذي يجب عليها، أما إن كانت جاءت من مصر ما نوت العمرة، جاءت لحاجة فلما وصلت جدة طرأ عليها العمرة وأنشأت العمرة من جديد نية جديدة فإحرامها صحيح من جدة وليس عليها شيء؛ لأنها لم تنو العمرة إلا من جدة لم تنشئها إلا من جدة، وهكذا مثلاً من جاء من الرياض إلى جدة أو من المدينة إلى جدة أو من الشام إلى جدة أو من غير ذلك وما عنده نية عمرة، فلما وصل جدة طرأ عليه وأنشأ العمرة وأحب أن يعتمر ليس عليه شيء، ميقات إحرامه صحيح لقول النبي ﷺ لما ذكر المواقيت قال: ومن كان دون ذلك -يعني دون المواقيت- فمهله من حيث أنشأ، حتى أهل مكة من مكة، يعني من كان دون المواقيت يكون إحرامه من حيث أنشأ النية نية الإحرام، جدة أو الشرايع أو التنعيم أو بالسلم أو غير ذلك إلا الحرم إذا كان في وسط الحرم يخرج إلى الحل، إذا طرأ عليه وهو في مكة أن يعتمر يخرج إلى الحل؛ لأن الرسول أمر عائشة أن تخرج إلى الحل عليه الصلاة والسلام لما أرادت العمرة قال: اخرجي إلى التنعيم التنعيم أدنى الحل، فإذا كان في مكة وطرأ عليه العمرة عن نفسه أو أبيه الميت أو أمه الميتة عن غيرهما من أمواته، أو عن أبيه العاجز لكبر سن أو مرض لا يرجى برؤه يخرج إلى الحل مثل عرفات مثل التنعيم تسمى مساجد عائشة مثل الجعرانة يعني خارج الأميال وراء الأميال من الحل ثم يلبي بالعمرة ويدخل. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8325/حكم-من-قدم-للعمرة-وتجاوز-الميقات-ولم-يحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30706.mp3","categories":["الإحرام","المواقيت"]},{"id":10153,"question":"سماحة الشيخ: متى تكون جدة ميقات؟","title":"الحال التي تكون فيها جدة ميقاتاً للحج والعمرة","answer":"الجواب: جدة ميقات لأهلها، وميقات لمن وصل إليها ما عنده نية عمرة ولا حج ثم طرأ عليه في جدة يحرم منها، وصل إلى جدة من أمريكا من أوروبا من أفريقيا من أي مكان ما عنده نية، إذا جاء جدة للتجارة أو لأسباب أخرى ثم بعدما وصلها أنشأ العمرة أحب أن يعتمر أو أحب أن يحج في وقت الحج يحرم من جدة ولا شيء عليه.\nالمقدم: جزاكم الله خيراً، هل هناك صنف ثالث؟\nالشيخ: إذا كان إنساناً لا يوازن الميقات إلا إذا وصل جدة، جاء من بلد لكن ليس في حذائه في البر أو في الجو ليست طائرته ولا سفينته تحاذي ميقاتاً إلا جدة ما يمر على ميقات حتى يصل جدة هذا يحرم من جدة إذا وجد، يقال إن بعض الخارجين من السودان أنه إذا جاء من جهة الغرب رأساً إنه ما يكون له ميقات إلا جدة إنه ما يحاذي شيء إلا جدة، من بور سودان، يقول بعض علماء السودان، فإذا وجد إنسان سافر من ميناء في السودان أو غيرها لا يحاذي ميقاتاً إلا جدة ما يمر على الميقات حتى يصل جدة يكون إحرامه من جدة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8326/الحال-التي-تكون-فيها-جدة-ميقاتا-للحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30707.mp3","categories":["المواقيت"]},{"id":10156,"question":"من يقول طالما أن الدم يسدد النقص وسوف أحرم من جدة، ما رأيكم؟","title":"حكم تعمد مجاوزة الميقات دون إحرام","answer":"الجواب: ما يجوز له يتعمد، بل يلزمه الميقات لأن الرسول ﷺ قال لما وقت المواقيت : هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد حجاً أو عمرة، وقال في اللفظ الآخر: يهل أهل المدينة من ذي الحليفة وأهل الشام من الجحفة معنى يهل هذا معناه الأمر، هو خبر بمعنى الأمر، وفي اللفظ الآخر: ليهل - باللام لام الأمر- ليهل أهل المدينة من ذي الحليفة وأهل الشام من الجحفة وأهل نجد من قرن وأهل اليمن من يلملم وأهل العراق من ذات عرق، فهذه مواقيت حددها الرسول ﷺ فعلى من أراد الحج أو العمرة أن يحرم منها إذا مرها وجوباً، إذا كان يريد الحج أو العمرة، أما إذا كان ما أراد إلا التجارة أو زيارة قريب أو صديق أو حاجات أخرى لا يلزمه الإحرام، لكنه يشرع له إلا إذا كان ما أدى العمرة عمرة الإسلام ولا حج حج الإسلام من مر عليها يلزمه الإحرام؛ لأنه وصل إلى مكة حينئذ استطاع، فإذا وصل إلى مكة وهو ما أدى عمرة الإسلام يحرم يلزمه الاعتمار، يعني يلزمه أن يحرم من الميقات بالعمرة لما من الله عليه بالاستطاعة أو جاء في وقت الحج يلزمه ذلك أيضاً إذا كان ما حج. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8327/حكم-تعمد-مجاوزة-الميقات-دون-احرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30708.mp3","categories":["الإحرام","المواقيت"]},{"id":10160,"question":"من يقول طالما أن الدم يسدد النقص وسوف أحرم من جدة، ما رأيكم؟","title":"حكم تعمد مجاوزة الميقات دون إحرام","answer":"الجواب: ما يجوز له يتعمد، بل يلزمه الميقات لأن الرسول ﷺ قال لما وقت المواقيت : هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد حجاً أو عمرة، وقال في اللفظ الآخر: يهل أهل المدينة من ذي الحليفة وأهل الشام من الجحفة معنى يهل هذا معناه الأمر، هو خبر بمعنى الأمر، وفي اللفظ الآخر: ليهل - باللام لام الأمر- ليهل أهل المدينة من ذي الحليفة وأهل الشام من الجحفة وأهل نجد من قرن وأهل اليمن من يلملم وأهل العراق من ذات عرق، فهذه مواقيت حددها الرسول ﷺ فعلى من أراد الحج أو العمرة أن يحرم منها إذا مرها وجوباً، إذا كان يريد الحج أو العمرة، أما إذا كان ما أراد إلا التجارة أو زيارة قريب أو صديق أو حاجات أخرى لا يلزمه الإحرام، لكنه يشرع له إلا إذا كان ما أدى العمرة عمرة الإسلام ولا حج حج الإسلام من مر عليها يلزمه الإحرام؛ لأنه وصل إلى مكة حينئذ استطاع، فإذا وصل إلى مكة وهو ما أدى عمرة الإسلام يحرم يلزمه الاعتمار، يعني يلزمه أن يحرم من الميقات بالعمرة لما من الله عليه بالاستطاعة أو جاء في وقت الحج يلزمه ذلك أيضاً إذا كان ما حج. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8327/حكم-تعمد-مجاوزة-الميقات-دون-احرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30708.mp3","categories":["الإحرام","المواقيت"]},{"id":10749,"question":"من الأفلاج المستمع سعد راشد بعث برسالة يقول فيها: ذهبت إلى مكة المكرمة بنية الحج والعمرة، وأحرمت من السيل ثم أديت جميع الشعائر المفروضة، وبعد أن طفت طواف الوداع ذهبت إلى المدينة المنورة للسلام على رسول الله ﷺ، ثم عدت إلى مكة المكرمة دون أن أحرم، فهل علي إثم في هذا وهل تلزمني كفارة؟ أرجو الإفادة جزاكم الله خيراً.","title":"حكم تجاوز الميقات دون إحرام، وشد الرحال لقبر النبي","answer":"الجواب: إذا كنت رجعت من المدينة بغير نية العمرة فلا شيء عليك، أما إذا كنت ناوياً العمرة فالواجب عليك أن تحرم من ميقات المدينة، فإذا لم تحرم من ميقات المدينة وأنت ناوي العمرة فعليك دم، إذا أحرمت من مكة أو من جدة أو نحو ذلك؛ لأنك تركت الميقات، أما إذا رجعت من دون إحرام ولا قصدت عمرة فلا شيء عليك، أو قصدت عمرة ولا أحرمت فعليك أن ترجع إلى الميقات وتحرم من الميقات إذا عزمت على العمرة، وإلا فلا عمرة عليك.\nولكن سفرك إلى المدينة من أجل السلام على الرسول ﷺ هذا ليس بمشروع، المشروع أن تقصد المسجد ثم يكون السلام تبعاً لذلك، هكذا جاءت الأحاديث عن رسول الله عليه الصلاة والسلام، في الحديث الصحيح يقول عليه الصلاة والسلام: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى، ما قال: لا تشد للسلام إلى كذا، قال: إلا إلى ثلاثة مساجد، فسمى المساجد.\nفالمشروع: أن يكون شد الرحال لقصد المساجد، فإذا جئت المسجد النبوي سلمت على الرسول ﷺ وعلى صاحبيه، وشرع لك أيضاً أن تزور البقيع وتسلم على أهل البقيع، كما يشرع لك أيضاً أن تزور مسجد قباء وتصلي فيه ركعتين، هذه كلها مشروعة لمن زار المدينة، لكن يكون القصد الأول في الرحلة الصلاة في المسجد النبوي، وإذا أردت مع ذلك السلام على الرسول عليه الصلاة والسلام فلا بأس يكون تبعاً لزيارة المسجد، أما أن تكون الرحلة أصلها كله أصلها للسلام على الرسول ﷺ وزيارة القبر هذا غير مشروع، ولكن تكون الرحلة لقصد المسجد، ولا بأس أن يكون معها وتضم إليها زيارة الرسول ﷺ والسلام عليه تبعاً للمسجد، ولكن الشيء الذي لا يصلح أن تكون الزيارة للقبر فقط والسلام على الرسول ﷺ.\nفينبغي التنبه لهذا؛ لأن الرسول عليه السلام قال: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى، فمعناه: أنه لا تشد الرحال لقصد زيارة القبور لا قبر النبي ﷺ ولا غيره، وإنما تشد لقصد هذه المساجد الثلاثة، وزيارة القبور تكون تبعاً إذا أتى المدينة زار قبر النبي ﷺ وسلم عليه وسلم على صاحبيه، شرع له أن يزور البقيع، يزور أحد الشهداء في أحد يسلم عليهم، تبعاً لهذه الزيارة للمسجد. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8923/حكم-تجاوز-الميقات-دون-احرام-وشد-الرحال-لقبر-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34606.mp3","categories":["الإحرام","المواقيت"]},{"id":11331,"question":"على بركة الله نبدأ هذا اللقاء بسؤال لأحد الإخوة من السودان يقول: سماحة الشيخ: كثيرًا ما واجهتنا هذه المسألة وهي بخصوص مواقيت الإحرام المكانية، وقد خصص الرسول ﷺ المواقيت المكانية لكل جهة من الأرض، ونحن في السودان غير محدد لنا ميقات مكاني ضمن تلك المواقيت، فمن أين نحرم سواءً أتينا بحرًا أو جوًا، علمًا بأنه عند دراستنا بالمدرسة علمونا بأننا أهل السودان نحرم من جدة، هل هذا صحيح وإن كان خطأ فمن أين نحرم مأجورين؟","title":"مواقيت الإحرام لمن أتى من السودان","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد. فقد صح عن النبي ﷺ أنه وقت لأهل النواحي كلها المواقيت الخمسة المعروفة، في الصحيحين من حديث ابن عباس -رضي الله عنهما- قال: وقت النبي ﷺ لأهل المدينة ذا الحليفة وهي معروفة تسمى الآن أبيار علي ولأهل الشام الجحفة وتسمى الآن رابغ، محل رابغ الآن ولأهل نجد قرن المنازل وهو المسمى بوادي قرن يسميه بعض العامة السيل ولأهل اليمن يلملم معروف أيضًا وفي رواية عائشة وجماعة: العراق ذات عرق. هذه خمسة مواقيت قال فيها النبي ﷺ في حديث ابن عباس: هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد الحج والعمرة ومن كان دون ذلك فمهله من حيث أنشأ حتى أهل مكة من مكة. فذو الحليفة للمدينة ومن أتى على طريق المدينة، والجحفة والآن يحرم الناس من رابغ قبلها بقليل ميقات لأهل الشام ومصر والمغرب والسودان كلهم من هذا الميقات، فالميقات لأهل السودان الجحفة، إذا حاذوها من طريق البحر أو من طريق الجو أحرموا، إلا أن يأتوا من طريق المدينة يحرموا من أبيار علي، من ذي الحليفة، أو يأتوا من طريق نجد يحرموا من ميقات أهل نجد وادي قرن -السيل- أو يؤتوا من طريق اليمن من كذلك يلملم، أو من طريق العراق ذات عرق. أما جدة فليست ميقات إلا لأهلها، جدة ميقات لأهلها الساكنين فيها، وأما النواحي الأخرى فليست ميقات لهم، لكن زعم بعض إخواننا في السودان أن بعض الطرق من السودان إذا سلكوها من البحر لا تحاذي الجحفة وإنما تحاذي جدة رأسًا قبل الجحفة، فإن صح هذا أن هناك طريقًا بحريًا من بور سودان أو غيرها من مواني السودان، إذا صح أن هناك طريقًا لا يمر بالجحفة بل يمر بجدة أولًا يحاذي جدة أولًا فإن الإحرام من جدة إن صح هذا، وإلا فالمعروف أن طريق أبناء السودان يمر أول شيء على الجحفة وهي رابغ الآن، ومن طريق الجو كذلك.  فعلى أبناء السودان أن يحرموا من الجحفة إذا حاذوها من جهة البحر، وهكذا إذا حاذوها من جهة البر، إلا إذا جاؤوا من طريق المدينة فمن ميقات المدينة وهكذا غيرهم وهكذا أهل مصر والشام والعراق.. أهل مصر والشام يأتون يحرمون من الجحفة. وهكذا أهل المغرب، أما أهل العراق من ذات عرق، إذا جاؤوا من طريق العراق أما إذا ذهبوا من المدينة فالميقات من المدينة، أو اليمن من ميقات اليمن، أما من كان دون ذلك من كان في .. مثلًا أو في البحرة يحرم من مكانه، يحرم من مكانه. نعم.","link":"https://binbaz.org.sa/fatwas/9513/مواقيت-الاحرام-لمن-اتى-من-السودان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29210.mp3","categories":["المواقيت"]},{"id":11372,"question":"هل من المستحب أداء العمرة في العشر الأواخر من رمضان؟ وهل هي أفضل من العشر الأوائل؟ وما مكانة محاولة تقبيل الحجر الأسود؟ جزاكم الله خيرًا.","title":"أفضل أوقات العمرة","answer":"الجواب:  العمرة في رمضان تعدل حجة كما قاله النبي ﷺ وفي العشر الأخيرة أفضل؛ لأن العشر الأخيرة هي أفضل الشهر، وهكذا في العشر الأول من ذي الحجة لها فضل عظيم؛ لأن عشر ذي الحجة أفضل الأيام، والعمل الصالح فيها أفضل الأعمال فإذا اعتمر في العشر الأول من ذي الحجة فلها فضل عظيم العمرة، لكن في رمضان أفضل؛ لقول النبي ﷺ: «عمرة في رمضان تعدل حجة». المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9552/افضل-اوقات-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37902.mp3","categories":["المواقيت"]},{"id":11380,"question":"هل من المستحب أداء العمرة في العشر الأواخر من رمضان؟ وهل هي أفضل من العشر الأوائل؟ وما مكانة محاولة تقبيل الحجر الأسود؟ جزاكم الله خيرًا.","title":"أفضل أوقات العمرة","answer":"الجواب:  العمرة في رمضان تعدل حجة كما قاله النبي ﷺ وفي العشر الأخيرة أفضل؛ لأن العشر الأخيرة هي أفضل الشهر، وهكذا في العشر الأول من ذي الحجة لها فضل عظيم؛ لأن عشر ذي الحجة أفضل الأيام، والعمل الصالح فيها أفضل الأعمال فإذا اعتمر في العشر الأول من ذي الحجة فلها فضل عظيم العمرة، لكن في رمضان أفضل؛ لقول النبي ﷺ: «عمرة في رمضان تعدل حجة». المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9552/افضل-اوقات-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37902.mp3","categories":["المواقيت"]},{"id":11529,"question":"من القصيم بريدة، المستمع: (ع. م .م) يقول: أنا شاب من مكة المكرمة، وأسكن حاليًا في منطقة القصيم للدراسة، وفي شهر رمضان الماضي والذي قبله ذهبت إلى مكة في أوائل شهر رمضان، وفي نيتي أن أؤدي مناسك العمرة في العشر الأواخر من رمضان، فجلست في مكة عند الأهل إلى العشر الأواخر، ثم أحرمت من منزلي في مكة، فأخبرني أحد الإخوة بأنني أخطأت، وكان الواجب علي أن أذهب إلى الميقات لأحرم، فهل علي شيء، مع العلم بأنني من أهل مكة -كما سبق وأن ذكرت- وأسكن مؤقتًا في القصيم للدراسة؟ جزاكم الله خيرًا.","title":"ما يجب على من أراد العمرة من أهل مكة؟","answer":"الجواب:  إذا كنت من أهل مكة، ولم تنو الإقامة في القصيم، وإنما جلست للدراسة فقط، وإلا فأنت على نية الاستيطان في مكة، والبقاء فيها، فليس عليك شيء، لكن إذا كنت أحرمت من مكة من نفس الحرم؛ فعليك دم يذبح في مكة للفقراء، أما إذا كنت خرجت إلى الحل كالجعرانة، أو عرفات، وأحرمت منها؛ فلا شيء عليك، نعم. المقدم: جزكم الله خيرًا، يقول: إن أحد الإخوة أخبره بأنه يجب عليه أن يخرج، وأن يحرم من خارج المنزل؟ الشيخ: لابد من دم ما دمت أحرمت من المنزل؛ فعليك دم يذبح في مكة للفقراء؛ لأن الواجب على أهل مكة إذا أرادوا العمرة أن يخرجوا إلى الحل كما أمر النبي ﷺ عائشة أن تخرج إلى الحل، فأحرمت من التنعيم، رضي الله عنها. المقصود: أن الأفقي الغريب لابد يحرم من الميقات إذا جاء، ... من الميقات الذي يمروا عليه، كالقصيمي يحرم من ميقات السيل، وهكذا الرياضي ونحوه، والذي يأتي مكة من المدينة من ميقات المدينة، وهكذا من يأتي من اليمن ميقات اليمن، أو من يأتي من الشام ميقات الشام، ومصر كالجحفة. المقصود: أن من كان في مكة، وأراد العمرة؛ فإنه يخرج إلى الحل كالتنعيم والجعرانة وعرفات، ونحو ذلك، فإذا أحرم من مكة نفسها؛ فعليه دم؛ لأنه أحرم من غير الميقات. المقدم: بارك الله فيكم، جزاكم الله خيرًا، إذًا ما قاله أخوه في ذلكم الوقت صحيح؟  الشيخ: الفتوى صواب، الفتوى صواب. المقدم: الحمد لله، بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9710/ما-يجب-على-من-اراد-العمرة-من-اهل-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38506.mp3","categories":["المواقيت"]},{"id":11907,"question":"المستمع جمال عبدالفتاح من جدة بعث برسالة وضمنها جمعًا من الأسئلة، في أحدها يقول: منذ خمس سنوات قدمت من العراق لأداء فريضة الحج بالطائرة، ولكن لم يكن معي إحرام، وعندما وصلت إلى مطار جدة اشتريت الإحرام، ونويت الحج والعمرة معًا، هل يلزمني فدية لتجاوزي الميقات؟ وهل يمكن أن أفدي في بلدي؟ جزاكم الله خيرًا.","title":"حكم تجاوز الميقات لعدم وجود ملابس الإحرام","answer":"الجواب:  نعم عليك ذبيحة تذبح بمكة للفقراء، ما هو في بلدك، تذبح في مكة، وعليك التوبة إلى الله من ذلك؛ لأنه لا يجوز تجاوز الميقات إلا بإحرام، وأنت أخطأت، تجاوزت بدون إحرام، لو أحرمت في ثيابك، ونويت العمرة إن كان عمرة أو حج، حج ثم غيرت في جدة؛ لا بأس، ويكون عليك فدية خاصة، فدية أقل من الذبيحة، فدية إطعام ستة مساكين، لكل مسكين نصف صاع عن لبس الثياب، أو صيام ثلاثة أيام، أو ذبح شاة، مخير. إذا أحرم الإنسان في ثيابه إن كان ما عنده محارم، وجاء الميقات ما عنده إزار ورداء؛ يحرم في قميصه، يكشف رأسه، ويحرم في قميص، وإذا وصل جدة يشتري ملابس الإحرام، ويلبس ملابس الإحرام، ويزيل القميص الذي عليه، وعليه الكفارة وهي مخيرة بين ثلاثة أمور: إما صيام ثلاثة أيام في كل مكان، أو إطعام ستة مساكين من فقراء الحرم، أو ذبح شاة توزع في فقراء الحرم، أما الصيام في كل مكان، ولا يجوز أن يتجاوز الميقات بغير إحرام، يحرم ولو في ثوبه، أو ...... على وسطه .... إزار ويحزمها عليه ............ والحمد لله. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10091/حكم-تجاوز-الميقات-لعدم-وجود-ملابس-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42608.mp3","categories":["المواقيت"]},{"id":11999,"question":"يسأل أيضًا، ويقول: من أين يحرم أهل السودان وهم في البحر؟ أيحرمون من جدة، أم من رابغ؟","title":"ميقات أهل السودان","answer":"الجواب:  ميقاتهم رابغ، إلا إذا مروا على ميقات قبل رابغ، وإلا فالذي نعرف عن السودان مثل مصر وغيرها ميقاتهم رابغ، لكن يقول بعض علماء السودان: إن هناك طريق قد تأتيه جدة قبل رابغ، يتصلون بجدة قبل رابغ، فإذا وجد طريقًا بهذا المسافة؛ أحرموا من جدة، أما إن كانوا يبادرون رابغ، أو من يلملم؛ لزمهم الإحرام وهم في البحر، إذا وازنوا هذا أو هذا، نعم. ﷺ: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10184/ميقات-اهل-السودان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43113.mp3","categories":["المواقيت"]},{"id":12400,"question":"من ينبع البحر المستمع سعيد بن سعيد بن علي بعث برسالة ضمنها جمعًا من الأسئلة، يقول: هل أهل جدة كلهم من داخل الميقات، أو من خارجه؟ ومن أين يحرمون؟ وكذلك أهل رابغ؟","title":"مكان إحرام أهل جدة ورابغ","answer":"الجواب:  أهل جدة كلهم من داخل الميقات، داخل الميقات الذي هو رابغ وما وراءه، ذي الحليفة هم داخل الميقات، فأهلها يحرمون من مكانهم؛ لقول النبي ﷺ لما وقت المواقيت قال: ومن كان دون ذلك فمهله من حيث أنشأ، حتى أهل مكة من مكة. فالذين في جدة، أو في .... أو في الشرايع، أو في بحرة، أو في أم السلم هؤلاء ميقاتهم بلدهم، يحرمون من مكانهم، إن أرادوا عمرة، أو حجًا، يحرمون من مكانهم، والذي في رابغ يحرم من رابغ، وهي ميقات الآن، هي الجحفة، والذي فوق الجحفة يحرم من مكانه؛ لأنه دون ذي الحليفة، فالحاصل أن المواقيت خمسة: ذو الحليفة: ميقات أهل المدينة. الجحفة: ميقات أهل الشام ومصر ونحوهم ممن يأتي من جهة الساحل، والآن يحرمون من رابغ، ورابغ قبل الجحفة بقليل من باب الاحتياط. الثالث: يلملم ميقات لأهل اليمن. الرابع: قرن المنازل، ويقال له: السيل ميقات لأهل نجد، وأهل الشرق. الخامس: ذات عرق، ويسمى: الضريبة ميقات لأهل العراق. فالذي يأتي قبل هذه المواقيت يحرم منها، الذي يأتي من طريق المدينة يحرم من ذي الحليفة، والذي يأتي من طريق الساحل من مصر، أو الشام، أو غيرها من طريق البحر يحرم من الجحفة رابغ، والذي يأتي من طريق اليمن جيزان واليمن يحرم من يلملم، والذي يأتي من العراق، وما حولها يحرم من الضريبة يعني: من ذات عرق، والذي يأتي من نجد، أو غيرها من جهة الشرق يحرم من السيل، من وادي قرن، وإذا كان دون هذه المواقيت كأهل جدة، وأهل الشرايع وأهل .... وأهل بحرة، وأشباههم يحرمون من محلهم؛ لقوله ﷺ: ومن كان دون ذلك فمهله من حيث أنشأ حتى أهل مكة من مكة أهل مكة يعني في الحج.  أما في العمرة يحرمون من خارج مكة؛ لأن الرسول ﷺ أمر عائشة أن تحرم بالعمرة من خارج مكة من التنعيم، وهكذا من الجعرانة، ومن عرفات يعني: خارج الحرم، من أراد العمرة وهو في مكة يتوجه إلى الحل، يخرج إلى الحل، ويلبي من هناك بالعمرة بعدما يغتسل في بيته، ويستعد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10605/مكان-احرام-اهل-جدة-ورابغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45505.mp3","categories":["المواقيت"]},{"id":12401,"question":"يقول: شخص قادم من لندن بالطائرة، ونزل في جدة، ولم يحرم قبل بدء سفره، ولم ينبهه عمال الطائرة عند المرور من الميقات، فكيف يحرم؟ وإذا نزل بجدة بدون إحرام، فماذا يلزمه؟","title":"حكم من نزل بالطائرة في جدة ولم يحرم مع محاذاة الميقات","answer":"الجواب:  إذا كان جاء من طريق الساحل من طريق البحر؛ يرجع إلى رابغ، ويحرم من رابغ، أما إن كان جاء من طريق المدينة؛ فليرجع إلى ميقات المدينة، وأما إذا كان ما يعلم محاذاة أي ميقات، الطريق الذي جاء من جهة الغرب، لا يعلم أنه حاذى لا ميقات رابغ، ولا غيره؛ فيحرم من جدة، ولكن إذا كانت الطائرة تحاذي رابغًا، تحاذي الجحفة؛ فإحرامه من رابغ، يرجع إليها على السيارات، ويحرم من رابغ.  وهكذا من جاء من طريق البحر، إذا حاذى رابغًا؛ يحرم من رابغ وهو في البحر، وهكذا في الجو إذا حاذى رابغًا في الجو، أو حاذى الحليفة إن كان من طريق المدينة يحرم من محاذاته في الجو، وإذا كان الملاح، ملاح الطائرة يعلم أنه ما حاذى رابغًا، ولا حاذى ميقاتًا آخر، إنما جاء من طريق يعني: غرب صامد، ما حاذى شيئًا، فميقاته جدة، إذا لم يحاذ ميقاتًا قبل ذلك، نعم. المقدم: بارك الله فيكم، الواقع هذه معلومة جديدة سماحة الشيخ -جزاكم الله خيرًا- لأن هناك كثيرًا من الناس يقولون: لماذا يحرم البعض من جدة؟ إذًا يحرم من جدة......؟ الشيخ: من لم يحاذ ميقاتًا قبل وصوله إليها في الجو، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10606/حكم-من-نزل-بالطاىرة-في-جدة-ولم-يحرم-مع-محاذاة-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45506.mp3","categories":["الإحرام","المواقيت"]},{"id":12646,"question":"هل تجوز فريضة الحج إذا أنشأت لها من خارج بلدي؟","title":"حكم من أنشأ سفراً لفريضة الحج من غير بلده","answer":"الجواب:  نعم، لا بأس إذا كنت مثلًا من أهل الرياض، وأنشأت السفر من المدينة، وأنت زرت المدينة، وأنشأت السفر منها إلى مكة بالحج؛ كفى ذلك، أو زرت جدة للحاجة، ثم أدركت الحج، وأحرمت من جدة؛ أجزأ الحج، أو مكة نفسها، زرتها لحاجة، أو لقريب، أو صديق، ثم جاء الحج؛ تحرم مع الناس بالحج، ويكفيك ذلك، ويجزئك، وعليك العمرة أيضًا إن كنت ما اعتمرت. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10856/حكم-من-انشا-سفرا-لفريضة-الحج-من-غير-بلده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45716.mp3","categories":["المواقيت"]},{"id":13685,"question":"يقول في سؤال له: أنا مصري ومقيم في خميس مشيط، وإن شاء الله أريد أن أؤدي فريضة الحج هذا العام، أريد أن أعرف من أي مكان يتم الإحرام للحج؟","title":"مواقيت الإحرام لمن هم جنوب المملكة","answer":"الجواب: يتم الإحرام من ميقات الطائف، ميقات نجد إذا جئت من طريق الطائف؛ تحرم من السيل، وادي قرن، وإن جئت من طريق الجبل؛ تحرم من يلملم ميقات أهل اليمن، هذا هو المشروع؛ لأن الرسول ﷺ لما وقت المواقيت الخمسة: ذي الحليفة، والجحفة، وقرن المنازل، ويلملم، وذات عرق، قال: هن لهن، ولمن أتى عليهن، من غير أهلهن، ممن أراد الحج والعمرة. فإذا جئت من طريق الطائف؛ تحرم من السيل، من طريق اليمن، تحرم من يلملم ميقات أهل اليمن، إذا بدأت بالمدينة؛ تحرم من ميقات المدينة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12036/مواقيت-الاحرام-لمن-هم-جنوب-المملكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51914.mp3","categories":["المواقيت"]},{"id":14803,"question":"المستمع: محمد صالح أبو العظام، من مصر، بعث برسالة يقول فيها: قبل ثمان سنوات كنت أعمل في الرياض، وتلقيت خبرًا من والدتي بأنها ستؤدي فريضة الحج، وعلي أن أستقبلها بمطار جدة، وبالفعل ذهبت لاستقبالها، ولأداء فريضة الحج معها، وقبل السفر سألت بعض الإخوة عن كيفية الإحرام؟فقالوا لي: تحرم من جدة، ولضيق الوقت لم أسأل غيرهم، فذهبت واستقبلت الوالدة، وأحرمت من جدة، وبعدها انتقل عملي إلى جدة، فحججت -ولله الحمد- مرتين، مرةً عن والدي، ومرةً عن جدي، ولكن ما يشغل بالي هو إحرامي من جدة في المرة الأولى، وأنا قادم من الرياض، فهل يكون حجي صحيحًا أم لا؟ وإذا كان غير صحيح هل علي أن أعيده، أم علي كفارة؟أفيدوني، جزاكم الله خيرًا.","title":"حكم حج من تجاوز الميقات وأحرم من جدة","answer":"الجواب: الحج صحيح، ولكن عليك دم واحد فدية؛ لأنك تركت الميقات، وهو وادي قرن، الذي يحرم منه أهل نجد، وأهل الطائف؛ لأنك حين خرجت من الديار قاصدًا الحج مع والدتك، فالواجب عليك الإحرام من ميقات أهل نجد، وهو السيل، وادي قرن، فعليك دم عن ترك ذلك، يذبح في مكة، وحجك صحيح، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إذا صادف أنه عاشر أهله -سماحة الشيخ- قبل أن يقدم هذا الهدي، فهل تنصحونه؟\nالشيخ: لا يضر، لا يضر، لا، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13310/حكم-حج-من-تجاوز-الميقات-واحرم-من-جدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64211.mp3","categories":["الإحرام","المواقيت"]},{"id":14811,"question":"المستمع: محمد صالح أبو العظام، من مصر، بعث برسالة يقول فيها: قبل ثمان سنوات كنت أعمل في الرياض، وتلقيت خبرًا من والدتي بأنها ستؤدي فريضة الحج، وعلي أن أستقبلها بمطار جدة، وبالفعل ذهبت لاستقبالها، ولأداء فريضة الحج معها، وقبل السفر سألت بعض الإخوة عن كيفية الإحرام؟فقالوا لي: تحرم من جدة، ولضيق الوقت لم أسأل غيرهم، فذهبت واستقبلت الوالدة، وأحرمت من جدة، وبعدها انتقل عملي إلى جدة، فحججت -ولله الحمد- مرتين، مرةً عن والدي، ومرةً عن جدي، ولكن ما يشغل بالي هو إحرامي من جدة في المرة الأولى، وأنا قادم من الرياض، فهل يكون حجي صحيحًا أم لا؟ وإذا كان غير صحيح هل علي أن أعيده، أم علي كفارة؟أفيدوني، جزاكم الله خيرًا.","title":"حكم حج من تجاوز الميقات وأحرم من جدة","answer":"الجواب: الحج صحيح، ولكن عليك دم واحد فدية؛ لأنك تركت الميقات، وهو وادي قرن، الذي يحرم منه أهل نجد، وأهل الطائف؛ لأنك حين خرجت من الديار قاصدًا الحج مع والدتك، فالواجب عليك الإحرام من ميقات أهل نجد، وهو السيل، وادي قرن، فعليك دم عن ترك ذلك، يذبح في مكة، وحجك صحيح، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إذا صادف أنه عاشر أهله -سماحة الشيخ- قبل أن يقدم هذا الهدي، فهل تنصحونه؟\nالشيخ: لا يضر، لا يضر، لا، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13310/حكم-حج-من-تجاوز-الميقات-واحرم-من-جدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64211.mp3","categories":["الإحرام","المواقيت"]},{"id":14816,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من المدينة المنورة، وادي القرع، وباعثها المستمع عبدالمعز عبدالباقي العسال، له جمع من الأسئلة، في أحد أسئلته يقول:ذهبت أنا وزوجتي لعمل العمرة في سيارة كانت متجهة من مكاننا في قرية تابعة للمدينة المنورة، تبعد عن رابغ تسعين كيلو متر عن الميقات، متجهة إلى جدة، عن طريق رابغ، وليست متجهة أصلًا إلى مكة المكرمة؛ ولما وصلنا الميقات في رابغ، قال لنا السائق: أحرموا من جدة بدلًا من أن تحرموا من الميقات وتدخلون معنا جدة، ففعلنا، ولم نحرم من الميقات.الشيخ: أعد أعد.المقدم: يقول: ذهبت أنا وزوجتي لعمل العمرة في سيارة كانت متجهة من مكاننا في قرية، تابعة للمدينة المنورة، تبعد عن رابغ تسعين كيلو متر عن الميقات، متجهة إلى جدة، عن طريق رابغ، وليست متجهة أصلًا إلى مكة المكرمة؛ ولما وصلنا الميقات في رابغ قال لنا السائق: أحرموا من جدة بدلًا من أن تحرموا من الميقات، وتدخلون معنا جدة، ففعلنا ولم نحرم من الميقات، وأحرمنا من جدة، وذهبنا في نفس الوقت إلى مكة، وعملنا العمرة، فما مدى صحة العمرة وصحة الإحرام؟ أفيدونا، جزاكم الله كل خير.","title":"حكم عمرة من أحرم من غير الميقات","answer":"الجواب: الإحرام صحيح، والعمرة صحيحة، ولكنها ناقصة؛ لأنكم تركتم الواجب، وهو الإحرام من الميقات، فعليكم دم ذبيحة واحدة عن كل واحد منكما تذبح في مكة للفقراء كالضحية، يعني: ذبيحة تجزي في الأضحية جذع ضأن، أو ثني معز، أو سبع بدنة، أو سبع بقرة، عن ترك الميقات.  أما العمرة فهي صحيحة، والحمد لله، والإحرام صحيح، لكن فيها نقص، عمرة ناقصة؛ بسبب الإخلال بالواجب وهو الإحرام من الميقات، تقبل الله من الجميع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13313/حكم-عمرة-من-احرم-من-غير-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64302.mp3","categories":["الإحرام","المواقيت"]},{"id":14947,"question":"سؤاله الأخير يقول: المسافر بالطائرة الذي لم يحرم إلا من جدة؛ لأن ملابس إحرامه كانت في الحقيبة والحقيبة في مخزن الأمتعة بالطائرة، وكان يعتقد أن الإحرام لا يصح إلا بملابس الإحرام، ما الذي عليه؟ جزاكم الله عنا خير الجزاء.","title":"ما حكم من أحرم من جدة لعدم توفر ملابس الإحرام؟","answer":"الجواب: الذي جاوز الميقات، وأتى جدة، وأحرم منها، عليه دم عند أكثر أهل العلم؛ لكونه ترك واجبًا عليه لعمرته أو حجه؛ ولقول ابن عباس -رضي الله تعالى عنهما-: «من ترك نسكًا، أو نسيه فليرق دمًا» يروى مرفوعًا إلى النبي ﷺ، ويروى موقوفًا عليه على ابن عباس، وهو أصح، لكنه في حكم الرفع؛ لأن مثل هذا الكلام تأسيس قاعدة شرعية، لا يقال من جهة الرأي؛ ولهذا أخذ به الجمهور، وقالوا: على مثل هذا دم؛ لأنه ترك واجبًا. ثم ينبغي لمثل هذا أن ينتبه، فإذا جاء وقت الإحرام وليس معه ملابس الإحرام يحرم فيما عليه، إن كان عليه سراويل كفت السراويل، ونزع القميص والعمامة، وجعل بعضها على كتفيه يكفي، ويبقى السراويل عليه، ولا عليه شيء، وإن شاء اتخذ قميصه إزارًا حتى يصل إلى جدة، وكفى، وأزال ما على رأسه. وبهذا يسلم من تجاوز الميقات بغير إحرام، ويسلم من الفدية، فإن أحرم على حاله فهو أولى، إن أحرم على حاله، ولم يغير فهو أولى من التأخير، لكن إذا أمكنه أن يخلع القميص، ويبقى عليه السراويل إذا كان عليه سراويل، فهذا هو الواجب عليه، يبقى في السراويل، ويزيل القميص والعمامة التي على رأسه، وهو مخير: إن شاء وضع القميص كذا على كتفيه، أو عمامته على كتفيه تقوم مقام الرداء، وإن شاء ترك، فإذا وصل إلى جدة أمكنه أن يغير، فإن لم يفعل؛ لزمه أن يحرم ولو على ثيابه هذه التي هي عليه، لزمه أن يحرم، وإذا وصل مكة، فدى بأحد ثلاثة: صيام ثلاثة أيام، أو إطعام ستة مساكين، أو ذبح شاة، كما أفتى النبي ﷺ بذلك كعب بن عجرة لما حلق رأسه. هذا الذي أحرم في ثيابه المخيطة وعمامته، ولم يخلعها؛ عليه أن يفدي بإحدى هذه الثلاث؛ إما صيام ثلاثة أيام، وإما إطعام ستة مساكين لكل مسكين نصف صاع من التمر، أو من الأرز، أو غيرهما من قوت البلد، وإما ذبح شاة، هذا عن المخيط، ومثل ذلك عن تغطية الرأس إذا لم يكشف رأسه، فيكون عليه كفارتان: إحداهما عن تغطية الرأس إذا لم يكشفه، والثانية عن المخيط الذي عليه، وهذا أولى له من التأخير من تأخير الإحرام إلى جدة ونحوها، بل يحرم وهو الواجب عليه، ويكون إحرامه في ثيابه، ويفدي هذه الفدية، لكن إذا أمكنه أن يخلعها ويبقى في السراويل؛ وجب عليه ذلك كما تقدم، نعم.","link":"https://binbaz.org.sa/fatwas/13460/ما-حكم-من-احرم-من-جدة-لعدم-توفر-ملابس-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_649/nour_64905.mp3","categories":["الإحرام","المواقيت"]},{"id":15019,"question":"المستمع محمد شكري عبداللطيف، مصري من محافظة الشرقية، ومقيم في مكة، حينما بعث الرسالة له جمع من الأسئلة في أحدها يقول:أنا أتيت إلى المملكة من أجل العمل، وأتيحت لي فرصة أداء فريضة الحج، فهل بذلك أكون قد تميت الركن الخامس للإسلام؛ لأني سمعت كثيرًا من الناس يقولون: لا يصح الحج إلا إذا كان الإنسان ذاهبًا للحج فقط، أفيدونا عن صحة هذا.جزاكم الله خيرًا.","title":"هل يشترط لصحة الحج أن يقصده الحاج من بلده؟","answer":"الجواب: الحج يجزئك عن فريضة الإسلام، ولو كنت ما قصدته من بلادك، وهذا الذي يقول بعض الناس: أن لا بد أن يأتي الحاج من بلاده لقصد الحج هذا باطل، لا أساس له.  المقصود وجود الحج، الله يقول سبحانه: وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97] ولم يقل: من داره، ولا من بيته، ولا من بلده، فإذا وصل إلى مكة أو جدة أو الطائف للعمل، ثم يسر الله له الحج وحج، فحجه صحيح، ويكفيه عن حجة الإسلام، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13515/هل-يشترط-لصحة-الحج-ان-يقصده-الحاج-من-بلده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49306.mp3","categories":["المواقيت"]},{"id":15475,"question":"هذه السائلة أم حسين من أبها تقول: بأنها سافرت مع الأهل من مدينة أبها إلى جدة بالطائرة؛ لأداء العمرة، ثم الذهاب إلى جدة، ولكنها حاضت فطلبت من الوالدة تأجيل الذهاب إلى مكة، وفعلًا تقول: ذهبنا إلى جدة أولًا، وبعد يومين أحرمنا جميعًا من جدة، ثم ذهبنا إلى مكة، وفعلنا العمرة، ثم رجعنا إلى جدة، وبعد سفرها إلى أبها، فما الحكم فيما فعلته يا سماحة الشيخ؟ هل عمرتهم صحيحة؟","title":"حكم من تجاوز ميقات بلده ولم يحرم منه","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالعمرة المذكورة صحيحة، ولكن عليهم دم؛ لأنهم أحرموا من جدة، وقد جاؤوا بالعمرة، وجاوزوا الميقات، فالواجب عليهم على كل واحد منهم دم يذبح في مكة للفقراء؛ لكونهم تجاوزوا الميقات، ولم يحرموا من الميقات، وإنما أحرموا من جدة، نسأل الله للجميع التوفيق والقبول. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/13999/حكم-من-تجاوز-ميقات-بلده-ولم-يحرم-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56901.mp3","categories":["المواقيت"]},{"id":15657,"question":"هذان سؤالان من المستمع عبيد نمر يوسف مصري يعمل بمكة المكرمة:سؤاله الأول يقول: أثناء إقامتي في مكة المكرمة أقوم كل يوم خميس بالإحرام بنية العمرة، وأؤدي عمرة، ولكني سمعت أن هذا لا يجوز، فلا بد أن يكون بين العمرة والعمرة أربعون يومًا، فهل هذا صحيح أم لا؟","title":"حكم تحديد أربعين يومًا بين العمرة والأخرى","answer":"الجواب: ليس بصحيح، ولا يشترط أن يكون بين العمرة والعمرة أربعون يومًا، هذا كلام لا أصل له، وإنما هو من كلام بعض العامة، ولا حرج في عمرته في الأسبوع مرتين، ما بين الخميس والخميس، أو السبت والسبت، أو أكثر من ذلك في كل عشرة أيام، أو نصف شهر، المقصود ليس فيه حد محدود، لا أربعون ولا غيرها، ولم يرد عن النبي ﷺ فيما نعلم حد محدود، فقد قال -عليه الصلاة والسلام-: العمرة إلى العمرة كفارة لما بينهما يروى عن علي  أنه قال: \"العمرة في كل شهر\" ولكن ليس هذا على سبيل التحديد، قد يكون قال ذلك على سبيل الأفضلية والرفق بالإنسان، وإلا فليس هناك حدًا محدودًا فيما نعلم، وإذا اعتمر في كل شهر، أو في كل شهرين، أو في كل نصف شهر، فلا نعلم في هذا بأسًا، نعم.","link":"https://binbaz.org.sa/fatwas/14202/حكم-تحديد-اربعين-يوما-بين-العمرة-والاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_699/nour_69908.mp3","categories":["المواقيت"]},{"id":15665,"question":"من الأخوين إبراهيم عوض الله محمد قرشي، وتركي عبدالله العنزي، رسالة يسألان فيها سماحتكم عمن تجاوز الميقات ولم يحرم إلا من جدة، ويقسمان في رسالتهما -سماحة الشيخ- أنهما لم يكونا يعلمان مكان الإحرام الصحيح؟جزاكم الله خيرًا.","title":"حكم من تجاوز الميقات ولم يحرم جاهلًا بذلك","answer":"الجواب: إذا تجاوز الإنسان الميقات وأحرم من دونه إلى مكة، فعليه دم يذبح في مكة للفقراء، ولو كان جاهلًا أو ناسيًا، لكن لا إثم عليه، إذا كان جاهلًا أو ناسيًا لا إثم عليه، ولكن عليه الدم؛ لقول ابن عباس -رضي الله عنهما-: \"من ترك نسكًا، أو نسيه فليهرق دمًا\" وهذا له حكم الرفع؛ لأنه لا يقال من جهة الرأي، قوله: \"أو نسيه\" يدل على أن الجاهل من باب أولى؛ لأن الناسي ليس باختياره، والجاهل يلزمه التعلم والسؤال، فإذا كان الناسي يفدي؛ فالجاهل من باب أولى. والواجب على المؤمن السؤال والتفقه في الدين والتعلم، يسأل عن أحكام العمرة ما يفعل فيها ما يقول فيها، أحكام الحج كذلك يسأل عنها، لا يسكت، المسلم يسأل وهكذا المسلمة، الله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43].  فالمقصود: أن الواجب على المؤمن والمؤمنة السؤال عن كل ما يتعلق بالدين والتفقه في ذلك في الحج في العمرة الصلاة الزكاة الصيام في كل شؤون الدين، الواجب على الجاهل أن يتعلم يتفقه ويسأل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14209/حكم-من-تجاوز-الميقات-ولم-يحرم-جاهلا-بذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70514.mp3","categories":["المواقيت"]},{"id":16467,"question":"الرسالة من الأخت أم أروى من شقراء، تقول: ما رأيكم في شخص توجه لزيارة أقارب له في مدينة جدة، وفي نيته أن يقوم بأداء العمرة إذا أتيحت له الفرصة لأداء العمرة، وعندما أتيحت له الفرصة أحرم من جدة، فهل ذلك مجزي؟ أم تنصحونه بشيء آخر؟ جزاكم الله خيرًا.","title":"حكم من أراد العمرة بعد أن تجاوز الميقات","answer":"الجواب: ليس عليه شيء ما دام نوى هذه النية إن أتيحت له الفرصة أحرم وإلا فلا، ما جزم، يكون بهذا غير جازم، فإذا يسر الله له الإحرام من جدة؛ فلا حرج.  أما الذي جزم بالعمرة من بلاده، سواء من المدينة، أو غيرها، هذا عليه أن يحرم من الميقات، إذا كان خرج من المدينة ناويًا جدة، ولكن ناويًا العمرة، جزم من المدينة أنه يعتمر؛ فعليه أن يحرم من الميقات، ميقات المدينة، ولا يجوز له أن يؤجل إلى جدة، فإن أجل؛ وجب عليه الرجوع إلى المدينة، ولا يجوز له أن يحرم من جدة، فإن أحرم من جدة؛ أثم، وعليه دم.  وهكذا لو كان في الطائف، وخرج إلى جدة ناويًا عمرة؛ يلزمه الرجوع إلى الميقات، فإن أحرم من جدة؛ فعليه دم يذبح في مكة للفقراء، أما الذي لا، ما جزم، بيقول: إن تيسر لي، إن سنحت الفرصة أحرمت؛ فهذا لا حرج عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15215/حكم-من-اراد-العمرة-بعد-ان-تجاوز-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81313.mp3","categories":["الإحرام","المواقيت"]},{"id":16902,"question":"يقول: ألاحظ أن بعض الناس مثلًا يأتون من مصر لأداء العمرة، لكنهم لا يحرمون من الميقات، بل يمكثون في جدة أيامًا، ثم بعد ذلك يحرمون من جدة، ويذهبون ليأتوا بالعمرة، ما حكم فعل هؤلاء؟ جزاكم الله خيرًا.","title":"حكم الإحرام من جدة لمن يأتي من خارجها","answer":"الجواب: إذا كانوا جاؤوا بنية العمرة من مصر، أو غيرها؛ فلابد أن يحرموا من الميقات، إن كانوا من طريق المدينة، من ميقات المدينة، وإن كان جاؤوا من طريق الساحل؛ أحرموا من الجحفة، من رابغ، سواء كانوا من مصر، أو الشام، أو غيرها، وإن جاؤوا من طريق نجد؛ أحرموا من وادي قرن السيل، وإن جاؤوا من طريق اليمن؛ أحرموا من ميقات اليمن يلملم، وإن جاؤوا من طريق العراق؛ أحرموا من ميقات أهل العراق، ذات عرق، يجب عليهم ذلك؛ لأن الرسول ﷺ لما وقت المواقيت قال: هن لهن، ولمن أتى عليهن، من غير أهلهن، ممن أراد الحج، أو العمرة فجعل المواقيت لجميع المارين عليها، فليس لأحد أن يتجاوزها بدون إحرام، إذا كان أراد حجًا، أو عمرة. أما إذا كانوا أتوا جدة، ما نووا حجًا، ولا عمرة، جاؤوا جدة للتجارة، أو لأسباب أخرى، ثم أنشؤوا نية العمرة، وبدا لهم ذلك من غير قصد سابق، بل من جديد بدؤوا نووا العمرة؛ يحرمون من جدة، لا بأس، سواء كانوا من الشام، أو من مصر، أو من نجد، أو من غير ذلك، إذا جاؤوا إلى جدة، ما نووا العمرة، لكن لما وصلوا إليها أنشؤوا من جديد نية العمرة، طرأ عليهم ذلك؛ فإنهم يحرمون من جدة، ولا حرج، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15660/حكم-الاحرام-من-جدة-لمن-ياتي-من-خارجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71909.mp3","categories":["المواقيت"]},{"id":17992,"question":"من أحد الإخوة المستمعين هو أحمد محمد عوض من الرياض يقول: أنا مقيم في مدينة الرياض هل يجوز لي زيارة أحد الأقارب في جدة ثم الإحرام من جدة كأهلها بنية أداء العمرة مع العلم بأن سبب سفري كان لأداء العمرة وزيارة هذا القريب في وقت واحد، ولقد سافرت بالطائرة مباشرة إلى جدة؟ أفيدونا جزاكم الله خيرًا.الشيخ: تعيده، الله المستعان.المقدم: يقول: أنا مقيم بمدينة الرياض هل يجوز لي زيارة أحد الأقارب في جدة ثم الإحرام من جدة كأهلها بنية أداء العمرة، مع العلم بأن سبب سفري كان لأداء العمرة وزيارة هذا القريب في وقت واحد، ولقد سافرت بالطائرة مباشرة إلى جدة؟","title":"حكم الإحرام من جدة لمن ليس من أهلها","answer":"الجواب: ما دمت تقصد العمرة والزيارة جميعًا من نفس بلدك فالواجب عليك أن تحرم من الميقات، أما إذا كنت ما قصدت إلا الزيارة، ثم بدا لك أن تعتمر فاحرم من جدة لا بأس، أما ما دمت قد عزمت على العمرة مع الزيارة من بلدك فعليك أن تحرم من الميقات لقوله ﷺ لما وقت المواقيت: هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد الحج أو العمرة وهذا محل إجماع بين أهل العلم ليس فيه خلاف والحمد لله. نعم.\nالمقدم: الحمد لله جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17031/حكم-الاحرام-من-جدة-لمن-ليس-من-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84916.mp3","categories":["الإحرام","المواقيت"]},{"id":18250,"question":"أم عبد العزيز من الرياض لها مجموعة الحقيقة من الأسئلة تقول: كم الوقت يا سماحة الشيخ الذي يجب أن يفصل بين الحج والحج، وبين العمرة والعمرة الأخرى؟ مأجورين.","title":"التوقيت بين الحج والحج وبين العمرة والعمرة","answer":"الجواب: ما أعلم في هذا حد، الحج معروف كل سنة، وليس فيه حد محدود، لو تيسر الحج في كل سنة الحمد لله، والعمرة ليس فيها حد محدود يقول ﷺ: العمرة إلى العمرة كفارة لما بينهما، والحج المبرور ليس له جزاء إلا الجنة فإذا هو اعتمر كل شهر أو كل شهرين أو أكثر أو أقل لا حرج في ذلك والحمد لله، إذا تيسر له ذلك. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17299/التوقيت-بين-الحج-والحج-وبين-العمرة-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78306.mp3","categories":["المواقيت"]},{"id":18459,"question":"تقول السائلة: من أين يحرم من منزله دون الميقات؟","title":"مكان الإحرام لمن منزله دون الميقات","answer":"الجواب: من كان منزله دون الميقات يحرم من محله من أهله؛ لقول النبي ﷺ لما وقت المواقيت قال: هن لهن، ولمن أتى عليهن من غير أهلهن ممن أراد الحج والعمرة، ثم قال عليه الصلاة والسلام: ومن كان دون ذلك فمهله من أهله، حتى أهل مكة من مكة، فإذا كان دون الميقات من الزيمة، في أم السلم، في جدة يحرم منها إذا أراد عمرة أو حجًا، والذي في بحرة يحرم منها، من أراد الحج أو العمرة، والذي في مكة يحرم منها بالحج، الذي في مكة يحرم بالحج منها، من بيته. أما العمرة يخرج إلى خارج الحل، إذا كانت عمرة وهو في مكة يخرج إلى الحل: التنعيم أو عرفات أو الجعرانة يحرم منها بالعمرة، إذا كان في مكة. نعم. المقدم: أحسن الله إليكم سماحة الشيخ، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17546/مكان-الاحرام-لمن-منزله-دون-الميقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78510.mp3","categories":["المواقيت"]},{"id":18751,"question":"هذه السائلة أم سلام من مكة المكرمة تسأل عن العمرة: من أين يحرم لها من المنزل أو من مسجد التنعيم بالنسبة لسكان مكة المكرمة فضيلة الشيخ؟","title":"موضع الإحرام لأهل مكة لمن أراد العمرة","answer":"الجواب: إذا أراد العمرة من هو ساكن في مكة يخرج إلى الحل: التنعيم، أو عرفات، أو الجعرانة أو غيرها، النبي ﷺ لما أراد العمرة وهو في أطراف مكة أحرم من الجعرانة، واعتمر عام الفتح، ولما أرادت عائشة العمرة وهي في مكة أمرها أن تخرج إلى الحل، أمر عبد الرحمن أخاها أن يخرج بها إلى الحل، فأحرمت من التنعيم، هذا هو السنة لأهل مكة، إذا أرادوا العمرة يخرجون خارج الحرم: عرفات، الجعرانة، التنعيم، يعني: خارج الحرم، يحرم بالعمرة ثم يدخل. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17880/موضع-الاحرام-لاهل-مكة-لمن-اراد-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79008.mp3","categories":["الإحرام","المواقيت"]},{"id":19255,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الدمام، وباعثها المستمع عبد القادر بن البناء، الأخ عبد القادر يقول: قدمت من مصر لأجل عمل عمرة وركبت المركب، ونزلت في جدة عند أخي الذي يعمل هناك، ولم يكن معي ملابس إحرام، وبعد يومين من جلوسي عند أخي اشترى لي ملابس الإحرام وذهبت وعملت عمرة، فهل العمرة صحيحة؟ وهل علي دم أو لا؟","title":"حكم من جاوز الميقات من دون إحرام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كنت نويت العمرة من بلادك فعليك دم؛ لأنك أحرمت من دون الميقات، ميقاتك رابغ وما يحاذيه، وقد جاوزته بدون إحرام؛ فعليك دم يذبح في مكة للفقراء مثل الضحية وهي رأس من الغنم، جذع ضأن أو ثني معز، يذبح للفقراء؛ لأنك تركت الواجب وهو الإحرام من الميقات والعمرة صحيحة والحمد لله، العمرة صحيحة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18448/حكم-من-جاوز-الميقات-من-دون-احرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73901.mp3","categories":["الإحرام","المواقيت"]},{"id":19583,"question":"يقول السائل: سافرت من أبها إلى جدة لقضاء بعض الأعمال، ونويت العمرة بعد الانتهاء من الأعمال، ثم أحرمت من جدة وأخذت العمرة، فهل عمرتي صحيحة؟","title":"حكم من أتى جدة لقضاء عمل ثم أحرم منها بالعمرة","answer":"الجواب: إذا كنت نويت العمرة من الأصل أنك سوف تأخذ العمرة فالواجب عليك الإحرام من الميقات حين تمر عليه، أو ترجع إليه بعد قضاء حاجتك من جدة ترجع إلى الميقات، وتحرم منه. أما إذا كنت ما نويت شيئًا إلا بعدما وصلت جدة، عزمت على العمرة بعد وصولك جدة، ونية جديدة؛ فلا بأس من الإحرام من جدة بعد فراغ شغلك. أما إذا كنت قد نويت من الأساس العمرة حين مررت على الميقات فالواجب الرجوع إلى الميقات عند قضاء حاجتك، قبل أن تذهب إلى العمرة، تذهب إلى الميقات، وتحرم منه بالعمرة، فإذا أحرمت من جدة ولم تأت الميقات فعليك دم يذبح في مكة للفقراء؛ لأنك قصدت العمرة، وأحرمت من غير ميقاتها تجاوزت ميقاتها، أما إذا كان لا إنما عزمت على العمرة بعد قضاء الشغل في جدة، ما نويت العمرة قبل ذلك فلا بأس. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18852/حكم-من-اتى-جدة-لقضاء-عمل-ثم-احرم-منها-بالعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94729.mp3","categories":["المواقيت"]}]
